-- Create admin role for a user to test admin access
-- You'll need to replace 'YOUR_USER_ID' with an actual user ID from your system

-- First, let's create a function to assign admin role to a user by email
CREATE OR REPLACE FUNCTION public.assign_admin_role(user_email TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    target_user_id UUID;
BEGIN
    -- Find the user by email
    SELECT id INTO target_user_id 
    FROM auth.users 
    WHERE email = user_email;
    
    -- Check if user exists
    IF target_user_id IS NULL THEN
        RAISE EXCEPTION 'User with email % not found', user_email;
    END IF;
    
    -- Insert admin role (ignore if already exists)
    INSERT INTO public.user_roles (user_id, role)
    VALUES (target_user_id, 'admin'::app_role)
    ON CONFLICT (user_id, role) DO NOTHING;
    
    RETURN TRUE;
END;
$$;

-- Example usage (commented out - replace with actual email):
-- SELECT public.assign_admin_role('your-admin-email@example.com');

-- ===== 20250923063940_05ad2c89-ea55-4165-8eae-ca51a3ffd4df.sql =====
-- Fix infinite recursion in user_roles RLS policies
-- The issue is that the admin policy references user_roles table within itself

-- First, drop the problematic policies
DROP POLICY IF EXISTS "Admins can manage all roles" ON user_roles;
DROP POLICY IF EXISTS "Users can view their own roles" ON user_roles;

-- Create a proper security definer function to check admin status
-- This bypasses RLS and prevents recursion
CREATE OR REPLACE FUNCTION public.is_admin(user_id UUID DEFAULT auth.uid())
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles 
    WHERE user_roles.user_id = $1 
    AND role = 'admin'::app_role
  );
$$;

-- Now create non-recursive policies using the security definer function
DROP POLICY IF EXISTS "Users can view their own roles" ON user_roles;
CREATE POLICY "Users can view their own roles" ON user_roles 
FOR SELECT 
TO authenticated
USING (auth.uid() = user_id);

-- For admin management, use the security definer function
DROP POLICY IF EXISTS "Admins can manage all roles" ON user_roles;
CREATE POLICY "Admins can manage all roles" ON user_roles 
FOR ALL 
TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

-- Also update the dealers policies to use the new security definer function
DROP POLICY IF EXISTS "Admins can view and manage all dealers" ON dealers;

DROP POLICY IF EXISTS "Admins can view and manage all dealers" ON dealers;
CREATE POLICY "Admins can view and manage all dealers" ON dealers 
FOR ALL 
TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

