GRANT EXECUTE ON FUNCTION public.get_public_dealer_by_seller(uuid) TO anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4 & 5. Guard privileged columns
-- ---------------------------------------------------------------------------
-- Guards only apply to direct API requests (current_user is anon/authenticated).
-- SECURITY DEFINER functions such as expire_featured_listings run as the owner
-- and are unaffected, as are the service role and admins.
CREATE OR REPLACE FUNCTION public.is_restricted_api_caller()
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path TO 'public'
AS $$
  SELECT current_user IN ('anon', 'authenticated') AND NOT public.is_admin();
$$;

-- car_listings ---------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_car_listing_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('pending_review', 'pending_payment') THEN
      RAISE EXCEPTION 'New listings must start as pending_review or pending_payment';
    END IF;
    IF NEW.listing_plan = 'free' AND NOT public.can_create_free_listing(NEW.user_id) THEN
      RAISE EXCEPTION 'Free listing limit reached';
    END IF;
    NEW.admin_created := false;
    NEW.is_featured := false;
    NEW.is_boosted := false;
    NEW.is_top_listing := false;
    NEW.featured_until := NULL;
    NEW.boosted_until := NULL;
    NEW.boost_approved_by := NULL;
    NEW.boost_approved_at := NULL;
    RETURN NEW;
  END IF;

  -- UPDATE: the only status change a seller may make is submitting payment
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (OLD.status = 'pending_payment' AND NEW.status = 'pending_review') THEN
    RAISE EXCEPTION 'Listing status can only be changed by an admin';
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.admin_created IS DISTINCT FROM OLD.admin_created
     OR NEW.is_featured IS DISTINCT FROM OLD.is_featured
     OR NEW.is_boosted IS DISTINCT FROM OLD.is_boosted
     OR NEW.is_top_listing IS DISTINCT FROM OLD.is_top_listing
     OR NEW.featured_until IS DISTINCT FROM OLD.featured_until
     OR NEW.boosted_until IS DISTINCT FROM OLD.boosted_until
     OR NEW.boost_approved_by IS DISTINCT FROM OLD.boost_approved_by
     OR NEW.boost_approved_at IS DISTINCT FROM OLD.boost_approved_at
     OR NEW.listing_plan IS DISTINCT FROM OLD.listing_plan
     OR NEW.listing_price IS DISTINCT FROM OLD.listing_price
     OR NEW.listing_duration IS DISTINCT FROM OLD.listing_duration
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
    RAISE EXCEPTION 'These listing fields can only be changed by an admin';
  END IF;

  RETURN NEW;
END;
$$;

-- Named so it fires before auto_approve_admin_listings (triggers fire alphabetically)
DROP TRIGGER IF EXISTS a_guard_car_listing_fields ON public.car_listings;
CREATE TRIGGER a_guard_car_listing_fields
  BEFORE INSERT OR UPDATE ON public.car_listings
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_car_listing_fields();

-- Count free listings server-side (previously done by the client, which could skip it)
CREATE OR REPLACE FUNCTION public.count_free_listing()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.admin_created OR NEW.listing_plan IS DISTINCT FROM 'free' THEN
    RETURN NEW;
  END IF;

  UPDATE public.dealers
  SET free_listings_used = free_listings_used + 1, updated_at = now()
  WHERE user_id = NEW.user_id AND status = 'verified';

  IF NOT FOUND THEN
    UPDATE public.profiles
    SET monthly_listings_used = COALESCE(monthly_listings_used, 0) + 1, updated_at = now()
    WHERE id = NEW.user_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS count_free_listing ON public.car_listings;
CREATE TRIGGER count_free_listing
  AFTER INSERT ON public.car_listings
  FOR EACH ROW
  EXECUTE FUNCTION public.count_free_listing();

-- dealers --------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_dealer_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.status := 'pending';
    NEW.payment_status := 'pending';
    NEW.admin_created := false;
    NEW.is_featured := false;
    NEW.featured_until := NULL;
    NEW.free_listings_used := 0;
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.payment_status IS DISTINCT FROM OLD.payment_status
     OR NEW.admin_created IS DISTINCT FROM OLD.admin_created
     OR NEW.is_featured IS DISTINCT FROM OLD.is_featured
     OR NEW.featured_until IS DISTINCT FROM OLD.featured_until
     OR NEW.free_listings_used IS DISTINCT FROM OLD.free_listings_used THEN
    RAISE EXCEPTION 'These dealer fields can only be changed by an admin';
  END IF;

  RETURN NEW;
END;
$$;

-- Named so it fires before auto_approve_admin_dealers
DROP TRIGGER IF EXISTS a_guard_dealer_fields ON public.dealers;
CREATE TRIGGER a_guard_dealer_fields
  BEFORE INSERT OR UPDATE ON public.dealers
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_dealer_fields();

-- profiles -------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_profile_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN
    RETURN NEW;
  END IF;

  -- check_monthly_listings_reset (fires earlier) may legitimately reset these
  -- once the reset date has passed; otherwise users may not touch them.
  IF OLD.monthly_listings_reset_date > now() THEN
    NEW.monthly_listings_used := OLD.monthly_listings_used;
    NEW.monthly_listings_reset_date := OLD.monthly_listings_reset_date;
  END IF;

  RETURN NEW;
END;
$$;

-- Named so it fires after check_monthly_listings_reset
DROP TRIGGER IF EXISTS z_guard_profile_fields ON public.profiles;
CREATE TRIGGER z_guard_profile_fields
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_profile_fields();

COMMIT;


-- ===== 20261029120000_listing_lifecycle.sql =====
-- Listing lifecycle: seller-managed availability, renewal, listing reports, readable settings.
-- Requires 20261021120000_security_hardening.sql (is_restricted_api_caller, guard triggers).
--
-- Adds columns and one table; no existing row is deleted. Existing listings get
-- availability_status = 'available' and no confirmation date, so they show as
-- "availability not confirmed" until their seller confirms. Expiry is NOT enforced here:
-- every active listing in production is already past expires_at.
-- Reverse with supabase/rollback/20261029120000_listing_lifecycle_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Availability, separate from moderation status
-- ---------------------------------------------------------------------------
-- status stays the moderation state (pending_review, active, rejected, ...).
-- availability_status is the seller's claim about the car itself.
ALTER TABLE public.car_listings
  ADD COLUMN IF NOT EXISTS availability_status text NOT NULL DEFAULT 'available',
  ADD COLUMN IF NOT EXISTS availability_confirmed_at timestamptz,
  ADD COLUMN IF NOT EXISTS sold_at timestamptz;

ALTER TABLE public.car_listings DROP CONSTRAINT IF EXISTS car_listings_availability_status_check;
ALTER TABLE public.car_listings
  ADD CONSTRAINT car_listings_availability_status_check
  CHECK (availability_status IN ('available', 'reserved', 'sold', 'unavailable'));

CREATE INDEX IF NOT EXISTS idx_car_listings_availability ON public.car_listings (status, availability_status);

-- Sellers change availability directly (existing "update own listing" policy). This trigger
-- keeps the timestamps honest: a seller cannot backdate or forward-date a confirmation.
CREATE OR REPLACE FUNCTION public.stamp_listing_availability()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.availability_confirmed_at := now();
    NEW.sold_at := NULL;
    NEW.availability_status := 'available';
    RETURN NEW;
  END IF;

  IF public.is_restricted_api_caller() THEN
    -- Any confirmation the seller sends is recorded as "now"
    IF NEW.availability_confirmed_at IS DISTINCT FROM OLD.availability_confirmed_at THEN
      NEW.availability_confirmed_at := now();
    END IF;
  END IF;

  IF NEW.availability_status IS DISTINCT FROM OLD.availability_status THEN
    NEW.availability_confirmed_at := now();
    NEW.sold_at := CASE WHEN NEW.availability_status = 'sold' THEN now() ELSE NULL END;
  ELSIF NEW.sold_at IS DISTINCT FROM OLD.sold_at THEN
    NEW.sold_at := OLD.sold_at;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS b_stamp_listing_availability ON public.car_listings;
CREATE TRIGGER b_stamp_listing_availability
  BEFORE INSERT OR UPDATE ON public.car_listings
  FOR EACH ROW
  EXECUTE FUNCTION public.stamp_listing_availability();

-- Make, model and year identify the car that was approved; sellers may not change them
-- afterwards (they would turn an approved listing into a different car).
CREATE OR REPLACE FUNCTION public.guard_listing_identity()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF public.is_restricted_api_caller()
     AND (NEW.make IS DISTINCT FROM OLD.make
          OR NEW.model IS DISTINCT FROM OLD.model
          OR NEW.year IS DISTINCT FROM OLD.year) THEN
    RAISE EXCEPTION 'Make, model and year cannot be changed after listing';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS a_guard_listing_identity ON public.car_listings;
CREATE TRIGGER a_guard_listing_identity
  BEFORE UPDATE ON public.car_listings
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_listing_identity();

-- ---------------------------------------------------------------------------
-- 2. Renewal
-- ---------------------------------------------------------------------------
-- expires_at is admin-only under the hardening guard, so renewal goes through this function:
-- the owner extends their own listing by its plan duration and confirms availability.
CREATE OR REPLACE FUNCTION public.renew_listing(listing_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  new_expiry timestamptz;
BEGIN
  UPDATE public.car_listings
  SET expires_at = now() + make_interval(days => COALESCE(listing_duration, 30)),
      availability_confirmed_at = now()
  WHERE id = listing_id
    AND user_id = auth.uid()
    AND status = 'active'
    AND availability_status IN ('available', 'reserved')
  RETURNING expires_at INTO new_expiry;

  IF new_expiry IS NULL THEN
    RAISE EXCEPTION 'Listing not found, not yours, or not active';
  END IF;
  RETURN new_expiry;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.renew_listing(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.renew_listing(uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 3. Listing reports
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.listing_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id uuid NOT NULL REFERENCES public.car_listings(id) ON DELETE CASCADE,
  reporter_id uuid NOT NULL DEFAULT auth.uid(),
  reason text NOT NULL CHECK (reason IN ('sold_or_unavailable', 'wrong_details', 'suspected_scam', 'duplicate', 'offensive', 'other')),
  details text CHECK (char_length(details) <= 1000),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'dismissed')),
  admin_notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz,
  resolved_by uuid
);

CREATE INDEX IF NOT EXISTS idx_listing_reports_status ON public.listing_reports (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_listing_reports_listing ON public.listing_reports (listing_id);
-- One open report per person per listing
CREATE UNIQUE INDEX IF NOT EXISTS idx_listing_reports_one_open
  ON public.listing_reports (listing_id, reporter_id) WHERE status = 'open';

ALTER TABLE public.listing_reports ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Signed-in users can report listings" ON public.listing_reports;
DROP POLICY IF EXISTS "Signed-in users can report listings" ON public.listing_reports;
CREATE POLICY "Signed-in users can report listings" ON public.listing_reports FOR INSERT
TO authenticated
WITH CHECK (reporter_id = auth.uid() AND status = 'open' AND resolved_at IS NULL AND resolved_by IS NULL AND admin_notes IS NULL);

DROP POLICY IF EXISTS "Reporters can view their own reports" ON public.listing_reports;
DROP POLICY IF EXISTS "Reporters can view their own reports" ON public.listing_reports;
CREATE POLICY "Reporters can view their own reports" ON public.listing_reports FOR SELECT
TO authenticated
USING (reporter_id = auth.uid());

DROP POLICY IF EXISTS "Admins can manage reports" ON public.listing_reports;
DROP POLICY IF EXISTS "Admins can manage reports" ON public.listing_reports;
CREATE POLICY "Admins can manage reports" ON public.listing_reports FOR ALL
TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

-- ---------------------------------------------------------------------------
-- 4. Settings readable by everyone
-- ---------------------------------------------------------------------------
-- The sell page reads listing_plans_enabled, but only admins could read app_settings, so
-- sellers always saw the default. Settings hold no secrets; writes stay admin-only.
DROP POLICY IF EXISTS "Anyone can read app settings" ON public.app_settings;
DROP POLICY IF EXISTS "Anyone can read app settings" ON public.app_settings;
CREATE POLICY "Anyone can read app settings" ON public.app_settings FOR SELECT
TO anon, authenticated
USING (true);

COMMIT;


-- ===== 20261105120000_platform_features_and_mid.sql =====
-- Platform feature switches and the Motorcars MID (Moatwave identity, interim version).
-- Requires 20261021120000_security_hardening.sql (applied first, as with the lifecycle migration).
--
-- Adds tables and functions only; no existing row is changed or deleted.
-- * platform_features: one row per Moatwave feature with the mode admins choose:
--   off | preview | motorcars (built here, interim) | moatwave (refused until the Moatwave connection exists).
-- * Versioned scoring config (PRD Part A3): point values and tier titles live in tables, never in code,
--   and a new version never re-scores entries already in the ledger.
-- * mid_identities: the MID, made from the account's phone number by the PRD rule (leading 0 dropped,
--   digits reversed). Marked unverified until SMS verification exists.
-- * mid_score_ledger: append-only points history; idempotent through a unique event key.
-- Reverse with supabase/rollback/20261105120000_platform_features_and_mid_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Feature switches
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.platform_features (
  feature text PRIMARY KEY CHECK (feature IN ('mid', 'wavechat', 'oio', 'conscience', 'argus')),
  mode text NOT NULL DEFAULT 'preview' CHECK (mode IN ('off', 'preview', 'motorcars', 'moatwave')),
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid REFERENCES auth.users (id) ON DELETE SET NULL
);

INSERT INTO public.platform_features (feature, mode)
VALUES ('mid', 'preview'), ('wavechat', 'preview'), ('oio', 'preview'), ('conscience', 'preview'), ('argus', 'preview')
ON CONFLICT (feature) DO NOTHING;

ALTER TABLE public.platform_features ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can read platform features" ON public.platform_features;
DROP POLICY IF EXISTS "Anyone can read platform features" ON public.platform_features;
CREATE POLICY "Anyone can read platform features" ON public.platform_features
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "Admins can change platform features" ON public.platform_features;
DROP POLICY IF EXISTS "Admins can change platform features" ON public.platform_features;
CREATE POLICY "Admins can change platform features" ON public.platform_features
  FOR UPDATE USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Replaced by a real check once a Moatwave connection is configured.
CREATE OR REPLACE FUNCTION public.moatwave_connected()
RETURNS boolean
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $$ SELECT false $$;

-- Features whose Motorcars version exists. Extended by each later feature migration.
CREATE OR REPLACE FUNCTION public.motorcars_feature_built(_feature text)
RETURNS boolean
LANGUAGE sql IMMUTABLE
SET search_path TO 'public'
AS $$ SELECT _feature IN ('mid') $$;

CREATE OR REPLACE FUNCTION public.guard_platform_feature_mode()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.mode = 'moatwave' AND NOT public.moatwave_connected() THEN
    RAISE EXCEPTION 'Moatwave is not connected yet, so % cannot be switched to Moatwave', NEW.feature;
  END IF;
  IF NEW.mode = 'motorcars' AND NOT public.motorcars_feature_built(NEW.feature) THEN
    RAISE EXCEPTION 'The Motorcars version of % is not built yet', NEW.feature;
  END IF;
  NEW.feature := OLD.feature;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS guard_platform_feature_mode ON public.platform_features;
CREATE TRIGGER guard_platform_feature_mode
  BEFORE UPDATE ON public.platform_features
  FOR EACH ROW EXECUTE FUNCTION public.guard_platform_feature_mode();

CREATE OR REPLACE FUNCTION public.feature_mode(_feature text)
RETURNS text
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $$ SELECT coalesce((SELECT mode FROM public.platform_features WHERE feature = _feature), 'off') $$;

-- ---------------------------------------------------------------------------
-- 2. Versioned scoring config
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.score_config_versions (
  id serial PRIMARY KEY,
  label text NOT NULL,
  is_active boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES auth.users (id) ON DELETE SET NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS score_config_one_active ON public.score_config_versions (is_active) WHERE is_active;

CREATE TABLE IF NOT EXISTS public.mid_point_rules (
  version_id integer NOT NULL REFERENCES public.score_config_versions (id) ON DELETE CASCADE,
  event_type text NOT NULL,
  points numeric(6, 2) NOT NULL,
  label text NOT NULL,
  PRIMARY KEY (version_id, event_type)
);

CREATE TABLE IF NOT EXISTS public.mid_tiers (
  version_id integer NOT NULL REFERENCES public.score_config_versions (id) ON DELETE CASCADE,
  min_score integer NOT NULL CHECK (min_score BETWEEN 0 AND 1000),
  title text NOT NULL,
  PRIMARY KEY (version_id, min_score)
);

-- Version 1: the Moatwave PRD point table (Section 7.1) and tiers (Section 5), mapped to car events.
-- Rules for events Motorcars has not built yet are seeded now so later features need no new version.
DO $$
DECLARE v integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.score_config_versions) THEN
    INSERT INTO public.score_config_versions (label, is_active)
    VALUES ('Motorcars interim 1 (from Moatwave PRD point table)', true)
    RETURNING id INTO v;

    INSERT INTO public.mid_point_rules (version_id, event_type, points, label) VALUES
      (v, 'registration_complete', 4, 'Personal registration complete'),
      (v, 'business_approved', 6, 'Dealer business approved'),
      (v, 'mid_generated', 10, 'MID generated'),
      (v, 'availability_confirmed', 0.3, 'Car availability confirmed'),
      (v, 'sale_recorded', 0.3, 'Car marked sold'),
      (v, 'receipt_sent', 0.2, 'Receipt sent'),
      (v, 'clean_cycle', 6, 'Clean 14-day Conscience cycle'),
      (v, 'two_clean_cycles_month', 8, 'Two clean cycles in one month'),
      (v, 'unreconciled_mismatch', -6, 'Unreconciled inventory mismatch'),
      (v, 'availability_lie', -8, 'Car shown available but already sold'),
      (v, 'failed_delivery_promise', -4, 'Failed promise reported through WaveChat');

    INSERT INTO public.mid_tiers (version_id, min_score, title) VALUES
      (v, 0, 'Unranked'),
      (v, 50, 'Market Man / Market Woman'),
      (v, 300, 'Oga Market / Market Madam'),
      (v, 500, 'Express Trader'),
      (v, 700, 'Chief Trader / Chief Madam'),
      (v, 850, 'Eze Afia / Lolo Afia'),
      (v, 930, 'Market Grand Commander');
  END IF;
END $$;

ALTER TABLE public.score_config_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mid_point_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mid_tiers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can read score config" ON public.score_config_versions;
DROP POLICY IF EXISTS "Anyone can read score config" ON public.score_config_versions;
CREATE POLICY "Anyone can read score config" ON public.score_config_versions FOR SELECT USING (true);
DROP POLICY IF EXISTS "Anyone can read point rules" ON public.mid_point_rules;
DROP POLICY IF EXISTS "Anyone can read point rules" ON public.mid_point_rules;
CREATE POLICY "Anyone can read point rules" ON public.mid_point_rules FOR SELECT USING (true);
DROP POLICY IF EXISTS "Anyone can read tiers" ON public.mid_tiers;
DROP POLICY IF EXISTS "Anyone can read tiers" ON public.mid_tiers;
CREATE POLICY "Anyone can read tiers" ON public.mid_tiers FOR SELECT USING (true);
-- No write policies: a new version is created through publish_score_config (admins only).

CREATE OR REPLACE FUNCTION public.publish_score_config(_label text, _rules jsonb)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  old_version integer;
  new_version integer;
  rule jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only admins can change point values';
  END IF;
  SELECT id INTO old_version FROM public.score_config_versions WHERE is_active;

  UPDATE public.score_config_versions SET is_active = false WHERE is_active;
  INSERT INTO public.score_config_versions (label, is_active, created_by)
  VALUES (_label, true, auth.uid()) RETURNING id INTO new_version;

  -- Start from the old version, then apply the changed values
  INSERT INTO public.mid_point_rules (version_id, event_type, points, label)
  SELECT new_version, event_type, points, label FROM public.mid_point_rules WHERE version_id = old_version;
  INSERT INTO public.mid_tiers (version_id, min_score, title)
  SELECT new_version, min_score, title FROM public.mid_tiers WHERE version_id = old_version;

  FOR rule IN SELECT * FROM jsonb_array_elements(coalesce(_rules, '[]'::jsonb)) LOOP
    UPDATE public.mid_point_rules
       SET points = (rule ->> 'points')::numeric
     WHERE version_id = new_version AND event_type = rule ->> 'event_type';
  END LOOP;

  RETURN new_version;
END;
$$;

-- ---------------------------------------------------------------------------
-- 3. MID identities
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.mid_identities (
  user_id uuid PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
  mid text NOT NULL UNIQUE CHECK (mid ~ '^[0-9]{10}$'),
  phone_verified boolean NOT NULL DEFAULT false,
  -- 'motorcars' while issued here; 'moatwave' once confirmed by Moatwave
  issued_by text NOT NULL DEFAULT 'motorcars' CHECK (issued_by IN ('motorcars', 'moatwave')),
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.mid_identities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users read their own MID" ON public.mid_identities;
DROP POLICY IF EXISTS "Users read their own MID" ON public.mid_identities;
CREATE POLICY "Users read their own MID" ON public.mid_identities
  FOR SELECT USING (auth.uid() = user_id OR public.is_admin());
-- No insert/update policies: MIDs are issued only by issue_my_mid.

-- Nigerian number → MID: 08031234567 / +2348031234567 / 2348031234567 → 8031234567 → reversed.
CREATE OR REPLACE FUNCTION public.mid_from_phone(_phone text)
RETURNS text
LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $$
DECLARE digits text := regexp_replace(coalesce(_phone, ''), '[^0-9]', '', 'g');
BEGIN
  IF digits ~ '^234[0-9]{10}$' THEN
    digits := substr(digits, 4);
  ELSIF digits ~ '^0[0-9]{10}$' THEN
    digits := substr(digits, 2);
  END IF;
  IF digits !~ '^[1-9][0-9]{9}$' THEN
    RETURN NULL;
  END IF;
  RETURN reverse(digits);
END;
$$;

-- ---------------------------------------------------------------------------
-- 4. Points ledger
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.mid_score_ledger (
  id bigserial PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  event_type text NOT NULL,
  points numeric(6, 2) NOT NULL,
  config_version_id integer NOT NULL REFERENCES public.score_config_versions (id),
  -- What earned the points, e.g. 'car_listings:<id>'; shown to the owner as evidence
  source_ref text,
  -- One award per real event, so retries never double-count
  event_key text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mid_score_ledger_user ON public.mid_score_ledger (user_id, created_at DESC);

ALTER TABLE public.mid_score_ledger ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users read their own points" ON public.mid_score_ledger;
DROP POLICY IF EXISTS "Users read their own points" ON public.mid_score_ledger;
CREATE POLICY "Users read their own points" ON public.mid_score_ledger
  FOR SELECT USING (auth.uid() = user_id OR public.is_admin());
-- No write policies: points are awarded only by award_mid_points.

-- Internal: awards points under the active config, only while the MID feature runs on Motorcars
-- and the person has a MID. Returns the points awarded (0 when nothing was recorded).
CREATE OR REPLACE FUNCTION public.award_mid_points(_user_id uuid, _event_type text, _event_key text, _source_ref text DEFAULT NULL)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v integer;
  pts numeric;
BEGIN
  IF public.feature_mode('mid') <> 'motorcars' THEN RETURN 0; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.mid_identities WHERE user_id = _user_id) THEN RETURN 0; END IF;

  SELECT id INTO v FROM public.score_config_versions WHERE is_active;
  SELECT points INTO pts FROM public.mid_point_rules WHERE version_id = v AND event_type = _event_type;
  IF pts IS NULL THEN RETURN 0; END IF;

  INSERT INTO public.mid_score_ledger (user_id, event_type, points, config_version_id, source_ref, event_key)
  VALUES (_user_id, _event_type, pts, v, _source_ref, _event_key)
  ON CONFLICT (event_key) DO NOTHING;
  RETURN CASE WHEN FOUND THEN pts ELSE 0 END;
END;
$$;
REVOKE ALL ON FUNCTION public.award_mid_points(uuid, text, text, text) FROM PUBLIC, anon, authenticated;

-- Score = sum of the ledger, kept within 0–1000.
CREATE OR REPLACE FUNCTION public.mid_score(_user_id uuid)
RETURNS numeric
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT least(1000, greatest(0, coalesce(sum(points), 0))) FROM public.mid_score_ledger WHERE user_id = _user_id
$$;
REVOKE ALL ON FUNCTION public.mid_score(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.mid_tier_title(_score numeric)
RETURNS text
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $$
  SELECT t.title FROM public.mid_tiers t
  JOIN public.score_config_versions v ON v.id = t.version_id AND v.is_active
  WHERE t.min_score <= _score ORDER BY t.min_score DESC LIMIT 1
$$;

-- ---------------------------------------------------------------------------
-- 5. Issuing a MID and reading MIDs
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.issue_my_mid()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  me uuid := auth.uid();
  new_mid text;
  existing text;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'Sign in to get a MID'; END IF;
  IF public.feature_mode('mid') <> 'motorcars' THEN RAISE EXCEPTION 'MID is not available yet'; END IF;

  SELECT mid INTO existing FROM public.mid_identities WHERE user_id = me;
  IF existing IS NOT NULL THEN RETURN existing; END IF;

  SELECT public.mid_from_phone(phone) INTO new_mid FROM public.profiles WHERE id = me;
  IF new_mid IS NULL THEN
    RAISE EXCEPTION 'Add a valid Nigerian phone number to your profile first';
  END IF;
  IF EXISTS (SELECT 1 FROM public.mid_identities WHERE mid = new_mid) THEN
    RAISE EXCEPTION 'This phone number already has a MID on another account. One person, one MID.';
  END IF;

  INSERT INTO public.mid_identities (user_id, mid) VALUES (me, new_mid);
  PERFORM public.award_mid_points(me, 'registration_complete', 'registration_complete:' || me);
  PERFORM public.award_mid_points(me, 'mid_generated', 'mid_generated:' || me);
  -- Dealers approved before they had a MID get their business points now
  IF EXISTS (SELECT 1 FROM public.dealers WHERE user_id = me AND status = 'verified') THEN
    PERFORM public.award_mid_points(me, 'business_approved', 'business_approved:' || me);
  END IF;
  RETURN new_mid;
END;
$$;
REVOKE ALL ON FUNCTION public.issue_my_mid() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.issue_my_mid() TO authenticated;

-- Public view of a person's MID: ring score, tier, verification. No ledger detail.
-- A MID is the phone number reversed, so the number itself is shown only where the phone number
-- already is public: approved dealers, and people who chose to show their phone number.
CREATE OR REPLACE FUNCTION public.get_public_mid(_user_id uuid)
RETURNS TABLE (mid text, score numeric, tier text, phone_verified boolean, issued_by text, cycles_sealed integer)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT CASE
           WHEN m.user_id = auth.uid()
             OR coalesce(p.show_phone_number, false)
             OR EXISTS (SELECT 1 FROM public.dealers d WHERE d.user_id = m.user_id AND d.status = 'verified')
           THEN m.mid
         END,
         public.mid_score(m.user_id), public.mid_tier_title(public.mid_score(m.user_id)),
         m.phone_verified, m.issued_by, 0
  FROM public.mid_identities m
  LEFT JOIN public.profiles p ON p.id = m.user_id
  WHERE m.user_id = _user_id AND public.feature_mode('mid') = 'motorcars'
$$;
GRANT EXECUTE ON FUNCTION public.get_public_mid(uuid) TO anon, authenticated;

-- Dealer approval earns the business points (PRD: business setup complete).
CREATE OR REPLACE FUNCTION public.award_business_approved()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.status = 'verified' AND OLD.status IS DISTINCT FROM 'verified' AND NEW.user_id IS NOT NULL THEN
    PERFORM public.award_mid_points(NEW.user_id, 'business_approved', 'business_approved:' || NEW.user_id);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS award_business_approved ON public.dealers;
CREATE TRIGGER award_business_approved
  AFTER UPDATE OF status ON public.dealers
  FOR EACH ROW EXECUTE FUNCTION public.award_business_approved();

COMMIT;


-- ===== 20261106120000_open_inventory.sql =====
-- Open Inventory (OIO), interim Motorcars version.
-- Requires, in order: 20261021120000_security_hardening.sql, 20261029120000_listing_lifecycle.sql,
-- 20261105120000_platform_features_and_mid.sql.
--
-- Every change to a car becomes a permanent event in inventory_events (Moatwave PRD Section 11:
-- state is historical, never destructive). The events are written by a trigger on car_listings,
-- so they record what actually happened to the row, not what any screen claims.
-- * Events are never updated or deleted, and survive the listing being deleted.
-- * Existing listings get one backfilled "listed" event (and "sold" where sold_at is set), marked
--   backfilled, because their earlier history was never recorded.
-- * Adds an optional VIN per car: one live listing per VIN, locked once set.
-- * Awards MID points for confirming availability (once per car per day) and for marking a car sold.
-- * Adds profiles.show_price_history and profiles.show_sales_count: each seller chooses whether buyers see
--   price changes and how many cars they have sold through Motorcars (both off by default).
-- Reverse with supabase/rollback/20261106120000_open_inventory_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. The event history
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.inventory_events (
  id bigserial PRIMARY KEY,
  -- Not a foreign key on purpose: history outlives a deleted listing
  listing_id uuid NOT NULL,
  seller_id uuid,
  event_type text NOT NULL CHECK (event_type IN (
    'submitted', 'listed', 'price_changed', 'availability_confirmed', 'reserved', 'made_available',
    'sold', 'withdrawn', 'renewed', 'vin_added'
  )),
  from_value jsonb,
  to_value jsonb,
  -- Snapshot so the event still reads correctly if the listing changes or is deleted
  car_title text NOT NULL,
  actor_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  -- true for events reconstructed when this migration ran, not recorded as they happened
  backfilled boolean NOT NULL DEFAULT false,
  -- Set once the event has been sent to Moatwave's Open Inventory
  synced_to_moatwave_at timestamptz
);
CREATE INDEX IF NOT EXISTS idx_inventory_events_listing ON public.inventory_events (listing_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_inventory_events_seller ON public.inventory_events (seller_id, occurred_at DESC);

ALTER TABLE public.inventory_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Sellers read their own inventory events" ON public.inventory_events;
DROP POLICY IF EXISTS "Sellers read their own inventory events" ON public.inventory_events;
CREATE POLICY "Sellers read their own inventory events" ON public.inventory_events
  FOR SELECT USING (auth.uid() = seller_id OR public.is_admin());
-- No insert/update/delete policies: only the trigger below writes events.

CREATE OR REPLACE FUNCTION public.keep_inventory_events()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  -- The only permitted change is marking an event as sent to Moatwave
  IF TG_OP = 'UPDATE'
     AND NEW.synced_to_moatwave_at IS DISTINCT FROM OLD.synced_to_moatwave_at
     AND (to_jsonb(NEW) - 'synced_to_moatwave_at') = (to_jsonb(OLD) - 'synced_to_moatwave_at') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Inventory history cannot be changed or deleted';
END;
$$;

DROP TRIGGER IF EXISTS keep_inventory_events ON public.inventory_events;
CREATE TRIGGER keep_inventory_events
  BEFORE UPDATE OR DELETE ON public.inventory_events
  FOR EACH ROW EXECUTE FUNCTION public.keep_inventory_events();

-- ---------------------------------------------------------------------------
-- 2. VIN
-- ---------------------------------------------------------------------------
ALTER TABLE public.car_listings ADD COLUMN IF NOT EXISTS vin text;
ALTER TABLE public.car_listings DROP CONSTRAINT IF EXISTS car_listings_vin_format;
ALTER TABLE public.car_listings
  ADD CONSTRAINT car_listings_vin_format CHECK (vin IS NULL OR vin ~ '^[A-HJ-NPR-Z0-9]{17}$');

-- The same car can't be live twice
CREATE UNIQUE INDEX IF NOT EXISTS car_listings_one_live_listing_per_vin
  ON public.car_listings (vin)
  WHERE vin IS NOT NULL
    AND status IN ('active', 'pending_review', 'pending_payment')
    AND availability_status IN ('available', 'reserved');

CREATE OR REPLACE FUNCTION public.guard_listing_vin()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  NEW.vin := nullif(upper(regexp_replace(coalesce(NEW.vin, ''), '\s', '', 'g')), '');
  IF TG_OP = 'UPDATE' AND OLD.vin IS NOT NULL AND NEW.vin IS DISTINCT FROM OLD.vin
     AND public.is_restricted_api_caller() THEN
    RAISE EXCEPTION 'The VIN cannot be changed once added. Contact support if it is wrong.';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS a_guard_listing_vin ON public.car_listings;
CREATE TRIGGER a_guard_listing_vin
  BEFORE INSERT OR UPDATE ON public.car_listings
  FOR EACH ROW EXECUTE FUNCTION public.guard_listing_vin();

-- ---------------------------------------------------------------------------
-- 3. Recording events
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.record_inventory_events()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  title text := concat_ws(' ', NEW.year, NEW.make, NEW.model);
  actor uuid := auth.uid();
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, to_value, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, CASE WHEN NEW.status = 'active' THEN 'listed' ELSE 'submitted' END,
            jsonb_build_object('price', NEW.price), title, actor);
    RETURN NEW;
  END IF;

  IF NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active' THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, to_value, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, 'listed', jsonb_build_object('price', NEW.price), title, actor);
  END IF;

  IF NEW.price IS DISTINCT FROM OLD.price THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, from_value, to_value, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, 'price_changed', jsonb_build_object('price', OLD.price),
            jsonb_build_object('price', NEW.price), title, actor);
  END IF;

  IF NEW.availability_status IS DISTINCT FROM OLD.availability_status THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, from_value, to_value, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id,
            CASE NEW.availability_status
              WHEN 'reserved' THEN 'reserved'
              WHEN 'sold' THEN 'sold'
              WHEN 'unavailable' THEN 'withdrawn'
              ELSE 'made_available'
            END,
            jsonb_build_object('availability', OLD.availability_status),
            jsonb_build_object('availability', NEW.availability_status), title, actor);

    IF NEW.availability_status = 'sold' AND NEW.user_id IS NOT NULL THEN
      PERFORM public.award_mid_points(NEW.user_id, 'sale_recorded', 'sale_recorded:' || NEW.id, 'car_listings:' || NEW.id);
    ELSIF NEW.availability_status = 'available' AND NEW.user_id IS NOT NULL THEN
      PERFORM public.award_mid_points(NEW.user_id, 'availability_confirmed',
        'availability_confirmed:' || NEW.id || ':' || current_date, 'car_listings:' || NEW.id);
    END IF;
  ELSIF NEW.availability_confirmed_at IS DISTINCT FROM OLD.availability_confirmed_at
        AND NEW.availability_confirmed_at IS NOT NULL THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, 'availability_confirmed', title, actor);
    IF NEW.user_id IS NOT NULL THEN
      PERFORM public.award_mid_points(NEW.user_id, 'availability_confirmed',
        'availability_confirmed:' || NEW.id || ':' || current_date, 'car_listings:' || NEW.id);
    END IF;
  END IF;

  IF NEW.expires_at IS NOT NULL AND (OLD.expires_at IS NULL OR NEW.expires_at > OLD.expires_at)
     AND OLD.status = 'active' THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, from_value, to_value, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, 'renewed', jsonb_build_object('expires_at', OLD.expires_at),
            jsonb_build_object('expires_at', NEW.expires_at), title, actor);
  END IF;

  IF NEW.vin IS NOT NULL AND OLD.vin IS NULL THEN
    INSERT INTO public.inventory_events (listing_id, seller_id, event_type, car_title, actor_id)
    VALUES (NEW.id, NEW.user_id, 'vin_added', title, actor);
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS z_record_inventory_events ON public.car_listings;
CREATE TRIGGER z_record_inventory_events
  AFTER INSERT OR UPDATE ON public.car_listings
  FOR EACH ROW EXECUTE FUNCTION public.record_inventory_events();

-- ---------------------------------------------------------------------------
-- 4. Backfill: what can be known about existing listings
-- ---------------------------------------------------------------------------
INSERT INTO public.inventory_events (listing_id, seller_id, event_type, to_value, car_title, occurred_at, backfilled)
SELECT l.id, l.user_id, 'listed', jsonb_build_object('price', l.price), concat_ws(' ', l.year, l.make, l.model), l.created_at, true
FROM public.car_listings l
WHERE l.status = 'active'
  AND NOT EXISTS (SELECT 1 FROM public.inventory_events e WHERE e.listing_id = l.id);

INSERT INTO public.inventory_events (listing_id, seller_id, event_type, to_value, car_title, occurred_at, backfilled)
SELECT l.id, l.user_id, 'sold', jsonb_build_object('availability', 'sold'), concat_ws(' ', l.year, l.make, l.model), l.sold_at, true
FROM public.car_listings l
WHERE l.sold_at IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM public.inventory_events e WHERE e.listing_id = l.id AND e.event_type = 'sold');

-- ---------------------------------------------------------------------------
-- 5. Reading
-- ---------------------------------------------------------------------------
-- Each seller decides whether buyers see their cars' price history and their sales count. Off by default.
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS show_price_history boolean NOT NULL DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS show_sales_count boolean NOT NULL DEFAULT false;

-- A car's public history: shown for live listings (and to their owner and admins).
-- Who acted is never exposed; submissions and VIN entries are left out. Unless the seller
-- chose to show price history, buyers see no price changes and no recorded prices at all.
-- prices_public tells the owner's screen what buyers can see.
CREATE OR REPLACE FUNCTION public.get_listing_history(_listing_id uuid)
RETURNS TABLE (event_type text, occurred_at timestamptz, from_value jsonb, to_value jsonb, backfilled boolean, prices_public boolean)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  WITH listing AS (
    SELECT l.status,
           (l.user_id = auth.uid() OR public.is_admin()) AS full_view,
           coalesce(p.show_price_history, false) AS prices_public
    FROM public.car_listings l
    LEFT JOIN public.profiles p ON p.id = l.user_id
    WHERE l.id = _listing_id
  )
  SELECT e.event_type, e.occurred_at,
         CASE WHEN v.full_view OR v.prices_public THEN e.from_value ELSE e.from_value - 'price' END,
         CASE WHEN v.full_view OR v.prices_public THEN e.to_value ELSE e.to_value - 'price' END,
         e.backfilled, v.prices_public
  FROM public.inventory_events e, listing v
  WHERE e.listing_id = _listing_id
    AND public.feature_mode('oio') = 'motorcars'
    AND (v.status = 'active' OR v.full_view)
    AND e.event_type NOT IN ('submitted', 'vin_added')
    AND (v.full_view OR v.prices_public OR e.event_type <> 'price_changed')
  ORDER BY e.occurred_at DESC, e.id DESC
  LIMIT 100
$$;
GRANT EXECUTE ON FUNCTION public.get_listing_history(uuid) TO anon, authenticated;

-- A stand's live stock at a glance, worked out from listings and events. The sold count is
-- returned only to the seller, admins, or anyone when the seller chose to show it.
CREATE OR REPLACE FUNCTION public.get_stand_inventory(_seller_id uuid)
RETURNS TABLE (available integer, reserved integer, sold_recorded integer, last_activity_at timestamptz)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    (SELECT count(*)::int FROM public.car_listings
      WHERE user_id = _seller_id AND status = 'active' AND availability_status = 'available'),
    (SELECT count(*)::int FROM public.car_listings
      WHERE user_id = _seller_id AND status = 'active' AND availability_status = 'reserved'),
    CASE WHEN _seller_id = auth.uid() OR public.is_admin()
              OR coalesce((SELECT show_sales_count FROM public.profiles WHERE id = _seller_id), false)
         THEN (SELECT count(DISTINCT listing_id)::int FROM public.inventory_events
                WHERE seller_id = _seller_id AND event_type = 'sold')
    END,
    (SELECT max(occurred_at) FROM public.inventory_events
      WHERE seller_id = _seller_id AND event_type <> 'submitted' AND NOT backfilled)
  WHERE public.feature_mode('oio') = 'motorcars'
$$;
GRANT EXECUTE ON FUNCTION public.get_stand_inventory(uuid) TO anon, authenticated;

-- The Motorcars version of Open Inventory now exists, so admins may switch it on
CREATE OR REPLACE FUNCTION public.motorcars_feature_built(_feature text)
RETURNS boolean
LANGUAGE sql IMMUTABLE
SET search_path TO 'public'
AS $$ SELECT _feature IN ('mid', 'oio') $$;

COMMIT;


-- ===== 20261107120000_wavechat.sql =====
-- WaveChat, interim Motorcars version.
-- Requires, in order: 20261021120000_security_hardening.sql, 20261029120000_listing_lifecycle.sql,
-- 20261105120000_platform_features_and_mid.sql, 20261106120000_open_inventory.sql.
--
-- Builds on the existing conversations/messages tables, so every past conversation carries over.
-- * Conversations gain a stage (enquiry → inspection → offer → agreed → completed).
-- * Messages gain a kind and a payload for structured actions. Structured actions run only through
--   wavechat_action(), which checks who may do what at which stage (Moatwave PRD Section 12: chat
--   becomes structured commercial events). An agreed offer is never a sale or a payment.
-- * Recording a sale issues a first-class receipt (sale_receipts), marks the car sold (recorded by
--   Open Inventory) and lets the buyer confirm it, linking receipt ↔ conversation ↔ car ↔ both people.
-- * Every action accepts a client-generated event id, so a retried tap never duplicates.
-- * Closes two gaps in the original chat rules: a conversation could be opened with anyone about any
--   car, and either person could edit the other's messages.
-- Reverse with supabase/rollback/20261107120000_wavechat_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Columns
-- ---------------------------------------------------------------------------
ALTER TABLE public.conversations
  ADD COLUMN IF NOT EXISTS stage text NOT NULL DEFAULT 'enquiry',
  ADD COLUMN IF NOT EXISTS inspection_at timestamptz,
  ADD COLUMN IF NOT EXISTS inspection_confirmed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS agreed_price numeric;
ALTER TABLE public.conversations DROP CONSTRAINT IF EXISTS conversations_stage_check;
ALTER TABLE public.conversations ADD CONSTRAINT conversations_stage_check
  CHECK (stage IN ('enquiry', 'inspection', 'offer', 'agreed', 'completed', 'closed'));

ALTER TABLE public.messages
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'text',
  ADD COLUMN IF NOT EXISTS action text,
  ADD COLUMN IF NOT EXISTS payload jsonb,
  ADD COLUMN IF NOT EXISTS client_event_id uuid;
ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_kind_check;
ALTER TABLE public.messages ADD CONSTRAINT messages_kind_check
  CHECK (kind IN ('text', 'action', 'offer', 'offer_response', 'receipt'));
CREATE UNIQUE INDEX IF NOT EXISTS messages_client_event_id ON public.messages (client_event_id) WHERE client_event_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 2. Receipts
-- ---------------------------------------------------------------------------
CREATE SEQUENCE IF NOT EXISTS public.sale_receipt_number_seq;

CREATE TABLE IF NOT EXISTS public.sale_receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  receipt_number text NOT NULL UNIQUE,
  conversation_id uuid NOT NULL REFERENCES public.conversations (id),
  listing_id uuid NOT NULL,
  buyer_id uuid NOT NULL,
  seller_id uuid NOT NULL,
  car_title text NOT NULL,
  amount numeric NOT NULL CHECK (amount > 0),
  payment_method text NOT NULL CHECK (payment_method IN ('cash', 'bank_transfer', 'pos', 'ussd', 'other')),
  issued_at timestamptz NOT NULL DEFAULT now(),
  buyer_confirmed_at timestamptz,
  synced_to_moatwave_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS sale_receipts_one_per_conversation ON public.sale_receipts (conversation_id);

ALTER TABLE public.sale_receipts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Buyer and seller read their receipts" ON public.sale_receipts;
DROP POLICY IF EXISTS "Buyer and seller read their receipts" ON public.sale_receipts;
CREATE POLICY "Buyer and seller read their receipts" ON public.sale_receipts
  FOR SELECT USING (auth.uid() IN (buyer_id, seller_id) OR public.is_admin());
-- No write policies: receipts are issued and confirmed only through wavechat_action.

-- ---------------------------------------------------------------------------
-- 3. Guards on the original tables
-- ---------------------------------------------------------------------------
-- Reads what the guard below needs but the caller's row-level access may hide.
CREATE OR REPLACE FUNCTION public.listing_open_for_chat(_listing_id uuid, _seller_id uuid)
RETURNS boolean
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT EXISTS (SELECT 1 FROM public.car_listings
                 WHERE id = _listing_id AND user_id = _seller_id AND status = 'active')
$$;

CREATE OR REPLACE FUNCTION public.seller_accepts_messages(_seller_id uuid)
RETURNS boolean
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _seller_id AND allow_messages = false)
$$;

-- A conversation is between a buyer and the seller of a live listing that accepts messages.
-- Must NOT be SECURITY DEFINER: is_restricted_api_caller() reads current_user, which would then be
-- the function owner, and every check here would be skipped.
CREATE OR REPLACE FUNCTION public.guard_conversation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.buyer_id = NEW.seller_id THEN
      RAISE EXCEPTION 'You cannot message yourself';
    END IF;
    IF NOT public.listing_open_for_chat(NEW.listing_id, NEW.seller_id) THEN
      RAISE EXCEPTION 'This listing is not available for messages';
    END IF;
    IF NOT public.seller_accepts_messages(NEW.seller_id) THEN
      RAISE EXCEPTION 'This seller has turned off messages';
    END IF;
    NEW.stage := 'enquiry';
    NEW.inspection_at := NULL;
    NEW.inspection_confirmed := false;
    NEW.agreed_price := NULL;
    RETURN NEW;
  END IF;

  -- UPDATE: participants may only touch the timestamp; everything else changes through wavechat_action
  IF NEW.listing_id IS DISTINCT FROM OLD.listing_id
     OR NEW.buyer_id IS DISTINCT FROM OLD.buyer_id
     OR NEW.seller_id IS DISTINCT FROM OLD.seller_id
     OR NEW.stage IS DISTINCT FROM OLD.stage
     OR NEW.inspection_at IS DISTINCT FROM OLD.inspection_at
     OR NEW.inspection_confirmed IS DISTINCT FROM OLD.inspection_confirmed
     OR NEW.agreed_price IS DISTINCT FROM OLD.agreed_price THEN
    RAISE EXCEPTION 'This conversation can only be changed through WaveChat actions';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS a_guard_conversation ON public.conversations;
CREATE TRIGGER a_guard_conversation
  BEFORE INSERT OR UPDATE ON public.conversations
  FOR EACH ROW EXECUTE FUNCTION public.guard_conversation();

-- People type plain text; structured messages come only from wavechat_action. The only change
-- anyone may make to a sent message is the recipient marking it read.
CREATE OR REPLACE FUNCTION public.guard_message()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.kind <> 'text' OR NEW.action IS NOT NULL OR NEW.payload IS NOT NULL THEN
      RAISE EXCEPTION 'Structured messages are sent through WaveChat actions';
    END IF;
    IF length(btrim(NEW.content)) = 0 OR length(NEW.content) > 2000 THEN
      RAISE EXCEPTION 'Messages must be between 1 and 2000 characters';
    END IF;
    NEW.is_read := false;
    NEW.created_at := now();
    RETURN NEW;
  END IF;

  IF NEW.sender_id = auth.uid()
     OR NEW.is_read IS NOT TRUE
     OR (to_jsonb(NEW) - 'is_read') <> (to_jsonb(OLD) - 'is_read') THEN
    RAISE EXCEPTION 'Sent messages cannot be changed';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS a_guard_message ON public.messages;
CREATE TRIGGER a_guard_message
  BEFORE INSERT OR UPDATE ON public.messages
  FOR EACH ROW EXECUTE FUNCTION public.guard_message();

-- ---------------------------------------------------------------------------
-- 4. Starting a conversation
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.start_wavechat(_listing_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  me uuid := auth.uid();
  seller uuid;
  conversation uuid;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'Sign in to message the seller'; END IF;
  IF public.feature_mode('wavechat') <> 'motorcars' THEN RAISE EXCEPTION 'WaveChat is not available yet'; END IF;

  SELECT user_id INTO seller FROM public.car_listings WHERE id = _listing_id AND status = 'active';
  IF seller IS NULL THEN RAISE EXCEPTION 'This listing is not available for messages'; END IF;
  IF seller = me THEN RAISE EXCEPTION 'You cannot message yourself'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = seller AND allow_messages = false) THEN
    RAISE EXCEPTION 'This seller has turned off messages';
  END IF;

  SELECT id INTO conversation FROM public.conversations
  WHERE listing_id = _listing_id AND buyer_id = me AND seller_id = seller;
  IF conversation IS NULL THEN
    INSERT INTO public.conversations (listing_id, buyer_id, seller_id)
    VALUES (_listing_id, me, seller) RETURNING id INTO conversation;
  END IF;
  RETURN conversation;
END;
$$;
REVOKE ALL ON FUNCTION public.start_wavechat(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.start_wavechat(uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 5. Structured actions
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.naira(_amount numeric)
RETURNS text
LANGUAGE sql IMMUTABLE
AS $$ SELECT '₦' || to_char(_amount, 'FM999,999,999,990') $$;

CREATE OR REPLACE FUNCTION public.wavechat_action(
  _conversation_id uuid,
  _action text,
  _payload jsonb DEFAULT '{}'::jsonb,
  _client_event_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  me uuid := auth.uid();
  c public.conversations%ROWTYPE;
  l public.car_listings%ROWTYPE;
  who text;
  existing uuid;
  msg_id uuid;
  amount numeric;
  offer public.messages%ROWTYPE;
  when_at timestamptz;
  method text;
  receipt public.sale_receipts%ROWTYPE;
  body text;
  msg_kind text := 'action';
  msg_payload jsonb;
  new_stage text;
  title text;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'Sign in to use WaveChat'; END IF;
  IF public.feature_mode('wavechat') <> 'motorcars' THEN RAISE EXCEPTION 'WaveChat is not available yet'; END IF;

  -- A retried tap returns the message it already created
  IF _client_event_id IS NOT NULL THEN
    SELECT id INTO existing FROM public.messages WHERE client_event_id = _client_event_id;
    IF existing IS NOT NULL THEN RETURN existing; END IF;
  END IF;

  SELECT * INTO c FROM public.conversations WHERE id = _conversation_id FOR UPDATE;
  IF NOT FOUND OR me NOT IN (c.buyer_id, c.seller_id) THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  who := CASE WHEN me = c.seller_id THEN 'seller' ELSE 'buyer' END;
  new_stage := c.stage;

  SELECT * INTO l FROM public.car_listings WHERE id = c.listing_id;
  title := concat_ws(' ', l.year, l.make, l.model);

  IF c.stage IN ('completed', 'closed') AND _action <> 'confirm_receipt' THEN
    RAISE EXCEPTION 'This conversation has ended';
  END IF;

  IF _action IN ('ask_availability', 'request_photos', 'book_inspection', 'make_offer', 'withdraw_offer', 'confirm_receipt')
     AND who <> 'buyer' THEN
    RAISE EXCEPTION 'Only the buyer can do that';
  END IF;
  IF _action IN ('confirm_available', 'reply_not_available', 'confirm_inspection', 'accept_offer', 'decline_offer', 'record_sale')
     AND who <> 'seller' THEN
    RAISE EXCEPTION 'Only the seller can do that';
  END IF;

  IF _action = 'ask_availability' THEN
    body := 'Is this car still available?';

  ELSIF _action = 'confirm_available' THEN
    IF l.availability_status <> 'available' THEN
      RAISE EXCEPTION 'This car is not marked available. Update its status first.';
    END IF;
    -- Answering in chat also confirms availability on the listing (recorded by Open Inventory)
    UPDATE public.car_listings SET availability_confirmed_at = now() WHERE id = l.id;
    body := 'Yes, it''s still available.';

  ELSIF _action = 'reply_not_available' THEN
    body := 'Sorry, this car is no longer available.';

  ELSIF _action = 'request_photos' THEN
    body := 'Could you send more photos, including the engine bay, the interior and any damage?';

  ELSIF _action = 'book_inspection' THEN
    when_at := (_payload ->> 'proposed_at')::timestamptz;
    IF when_at IS NULL OR when_at < now() THEN RAISE EXCEPTION 'Choose a time in the future for the inspection'; END IF;
    UPDATE public.conversations SET inspection_at = when_at, inspection_confirmed = false WHERE id = c.id;
    body := 'I''d like to inspect the car on ' || to_char(when_at AT TIME ZONE 'Africa/Lagos', 'FMDay DD Mon, HH12:MI AM') || '.';
    msg_payload := jsonb_build_object('proposed_at', when_at);
    IF c.stage = 'enquiry' THEN new_stage := 'inspection'; END IF;

  ELSIF _action = 'confirm_inspection' THEN
    IF c.inspection_at IS NULL THEN RAISE EXCEPTION 'The buyer has not asked for an inspection yet'; END IF;
    UPDATE public.conversations SET inspection_confirmed = true WHERE id = c.id;
    body := 'Inspection confirmed for ' || to_char(c.inspection_at AT TIME ZONE 'Africa/Lagos', 'FMDay DD Mon, HH12:MI AM') || '.';
    msg_payload := jsonb_build_object('inspection_at', c.inspection_at);

  ELSIF _action = 'make_offer' THEN
    amount := round((_payload ->> 'amount')::numeric);
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter an offer above zero'; END IF;
    -- A new offer replaces any offer still waiting for an answer
    UPDATE public.messages SET payload = payload || '{"status":"replaced"}'
    WHERE conversation_id = c.id AND kind = 'offer' AND payload ->> 'status' = 'pending';
    msg_kind := 'offer';
    msg_payload := jsonb_build_object('amount', amount, 'status', 'pending');
    body := 'Offer: ' || public.naira(amount) || '. An offer in chat is not a sale or a payment.';
    IF c.stage IN ('enquiry', 'inspection') THEN new_stage := 'offer'; END IF;

  ELSIF _action IN ('accept_offer', 'decline_offer', 'withdraw_offer') THEN
    SELECT * INTO offer FROM public.messages
    WHERE id = (_payload ->> 'offer_id')::uuid AND conversation_id = c.id AND kind = 'offer' FOR UPDATE;
    IF NOT FOUND OR offer.payload ->> 'status' <> 'pending' THEN
      RAISE EXCEPTION 'That offer is no longer open';
    END IF;
    amount := (offer.payload ->> 'amount')::numeric;
    UPDATE public.messages
    SET payload = payload || jsonb_build_object('status',
      CASE _action WHEN 'accept_offer' THEN 'accepted' WHEN 'decline_offer' THEN 'declined' ELSE 'withdrawn' END)
    WHERE id = offer.id;
    msg_kind := 'offer_response';
    msg_payload := jsonb_build_object('offer_id', offer.id, 'amount', amount);
    IF _action = 'accept_offer' THEN
      UPDATE public.conversations SET agreed_price = amount WHERE id = c.id;
      new_stage := 'agreed';
      body := 'Offer of ' || public.naira(amount) || ' accepted. This is an agreement in chat, not a sale or a payment.';
    ELSIF _action = 'decline_offer' THEN
      body := 'Offer of ' || public.naira(amount) || ' declined.';
    ELSE
      body := 'Offer of ' || public.naira(amount) || ' withdrawn.';
    END IF;

  ELSIF _action = 'record_sale' THEN
    amount := round((_payload ->> 'amount')::numeric);
    method := _payload ->> 'payment_method';
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter the amount paid'; END IF;
    IF method IS NULL OR method NOT IN ('cash', 'bank_transfer', 'pos', 'ussd', 'other') THEN
      RAISE EXCEPTION 'Choose how the buyer paid';
    END IF;
    IF l.availability_status = 'sold' THEN RAISE EXCEPTION 'This car is already marked sold'; END IF;

    INSERT INTO public.sale_receipts (receipt_number, conversation_id, listing_id, buyer_id, seller_id, car_title, amount, payment_method)
    VALUES ('MC-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.sale_receipt_number_seq')::text, 6, '0'),
            c.id, l.id, c.buyer_id, c.seller_id, title, amount, method)
    RETURNING * INTO receipt;

    -- The car is sold: Open Inventory records it and the seller's MID gets the sale points
    UPDATE public.car_listings SET availability_status = 'sold' WHERE id = l.id;
    PERFORM public.award_mid_points(c.seller_id, 'receipt_sent', 'receipt_sent:' || receipt.id, 'sale_receipts:' || receipt.id);

    msg_kind := 'receipt';
    msg_payload := jsonb_build_object('receipt_id', receipt.id, 'receipt_number', receipt.receipt_number, 'amount', amount, 'payment_method', method);
    body := 'Sale recorded: ' || public.naira(amount) || '. Receipt ' || receipt.receipt_number || '.';
    new_stage := 'completed';

  ELSIF _action = 'confirm_receipt' THEN
    UPDATE public.sale_receipts SET buyer_confirmed_at = now()
    WHERE conversation_id = c.id AND buyer_id = me AND buyer_confirmed_at IS NULL
    RETURNING * INTO receipt;
    IF receipt.id IS NULL THEN RAISE EXCEPTION 'There is no receipt to confirm'; END IF;
    msg_payload := jsonb_build_object('receipt_id', receipt.id);
    body := 'I confirm receipt ' || receipt.receipt_number || ' is correct.';

  ELSE
    RAISE EXCEPTION 'Unknown WaveChat action %', _action;
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, kind, action, payload, client_event_id)
  VALUES (c.id, me, body, msg_kind, _action, msg_payload, _client_event_id)
  RETURNING id INTO msg_id;

  UPDATE public.conversations SET stage = new_stage, updated_at = now() WHERE id = c.id;
  RETURN msg_id;
END;
$$;
REVOKE ALL ON FUNCTION public.wavechat_action(uuid, text, jsonb, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.wavechat_action(uuid, text, jsonb, uuid) TO authenticated;

-- Receipts stay as issued; only the buyer's confirmation (set above) and the Moatwave sync mark change.
CREATE OR REPLACE FUNCTION public.keep_sale_receipts()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND (to_jsonb(NEW) - 'buyer_confirmed_at' - 'synced_to_moatwave_at')
       = (to_jsonb(OLD) - 'buyer_confirmed_at' - 'synced_to_moatwave_at')
     AND (OLD.buyer_confirmed_at IS NULL OR NEW.buyer_confirmed_at = OLD.buyer_confirmed_at) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Receipts cannot be changed or deleted';
END;
$$;

DROP TRIGGER IF EXISTS keep_sale_receipts ON public.sale_receipts;
CREATE TRIGGER keep_sale_receipts
  BEFORE UPDATE OR DELETE ON public.sale_receipts
  FOR EACH ROW EXECUTE FUNCTION public.keep_sale_receipts();

-- The Motorcars version of WaveChat now exists, so admins may switch it on
CREATE OR REPLACE FUNCTION public.motorcars_feature_built(_feature text)
RETURNS boolean
LANGUAGE sql IMMUTABLE
SET search_path TO 'public'
AS $$ SELECT _feature IN ('mid', 'oio', 'wavechat') $$;

COMMIT;


-- ===== 20261108120000_wavechat_conversation_features.sql =====
-- WaveChat: everyday chat features and the WaveChat sales records.
-- Requires 20261107120000_wavechat.sql (and everything it requires).
--
-- Chat: photo, document and voice-note attachments (private bucket, only the two people in the
-- conversation can open them), replies, one reaction per person per message, delete-for-everyone
-- for your own plain messages, delivered/read times, last seen, unread counts.
-- Sales records (Moatwave PRD Sections 12, 14.4, 22): seller quotes, deposit and part-payment
-- receipts, buyer payment promises with due dates (kept on time earns MID points), and a handover
-- checklist both sides confirm. Recording the final payment no longer ends the conversation:
-- the stages now run enquiry → inspection → offer → agreed → paid → completed (handed over).
-- Structured records (offers, quotes, receipts, promises, handover) can never be deleted.
-- Reverse with supabase/rollback/20261108120000_wavechat_conversation_features_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Stages and message kinds
-- ---------------------------------------------------------------------------
ALTER TABLE public.conversations DROP CONSTRAINT IF EXISTS conversations_stage_check;
ALTER TABLE public.conversations ADD CONSTRAINT conversations_stage_check
  CHECK (stage IN ('enquiry', 'inspection', 'offer', 'agreed', 'paid', 'completed', 'closed'));
-- Conversations completed under the earlier rule had their final payment recorded
UPDATE public.conversations SET stage = 'paid' WHERE stage = 'completed';

ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_kind_check;
ALTER TABLE public.messages ADD CONSTRAINT messages_kind_check
  CHECK (kind IN ('text', 'action', 'offer', 'offer_response', 'quote', 'quote_response', 'payment', 'promise', 'receipt', 'handover'));

-- ---------------------------------------------------------------------------
-- 2. Message columns: replies, attachments, delivery, deletion
-- ---------------------------------------------------------------------------
ALTER TABLE public.messages
  ADD COLUMN IF NOT EXISTS reply_to_id uuid REFERENCES public.messages (id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS attachment_path text,
  ADD COLUMN IF NOT EXISTS attachment_type text,
  ADD COLUMN IF NOT EXISTS attachment_name text,
  ADD COLUMN IF NOT EXISTS attachment_size integer,
  ADD COLUMN IF NOT EXISTS attachment_duration integer,
  ADD COLUMN IF NOT EXISTS delivered_at timestamptz,
  ADD COLUMN IF NOT EXISTS read_at timestamptz,
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_attachment_type_check;
ALTER TABLE public.messages ADD CONSTRAINT messages_attachment_type_check
  CHECK (attachment_type IS NULL OR attachment_type IN ('image', 'file', 'voice'));
CREATE INDEX IF NOT EXISTS idx_messages_unread ON public.messages (conversation_id) WHERE is_read = false;

-- Plain messages may carry an attachment instead of words. Replies stay inside their conversation.
-- The only direct change to a sent message is the recipient marking it delivered or read.
CREATE OR REPLACE FUNCTION public.guard_message()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_restricted_api_caller() THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.kind <> 'text' OR NEW.action IS NOT NULL OR NEW.payload IS NOT NULL THEN
      RAISE EXCEPTION 'Structured messages are sent through WaveChat actions';
    END IF;
    IF NEW.attachment_path IS NOT NULL THEN
      IF NEW.attachment_path NOT LIKE NEW.conversation_id::text || '/%'
         OR NEW.attachment_type IS NULL
         OR coalesce(NEW.attachment_size, 0) NOT BETWEEN 1 AND 10485760
         OR length(coalesce(NEW.attachment_name, '')) > 200 THEN
        RAISE EXCEPTION 'That attachment is not valid';
      END IF;
    ELSIF length(btrim(NEW.content)) = 0 THEN
      RAISE EXCEPTION 'Messages cannot be empty';
    END IF;
    IF length(NEW.content) > 2000 THEN RAISE EXCEPTION 'Messages can be up to 2000 characters'; END IF;
    IF NEW.reply_to_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.messages WHERE id = NEW.reply_to_id AND conversation_id = NEW.conversation_id) THEN
      RAISE EXCEPTION 'You can only reply to a message in this conversation';
    END IF;
    NEW.is_read := false;
    NEW.created_at := now();
    NEW.delivered_at := NULL;
    NEW.read_at := NULL;
    NEW.deleted_at := NULL;
    RETURN NEW;
  END IF;

  IF NEW.sender_id = auth.uid()
     OR (to_jsonb(NEW) - 'is_read' - 'read_at' - 'delivered_at') <> (to_jsonb(OLD) - 'is_read' - 'read_at' - 'delivered_at')
     OR (OLD.is_read AND NOT NEW.is_read) THEN
    RAISE EXCEPTION 'Sent messages cannot be changed';
  END IF;
  IF NEW.is_read AND NOT OLD.is_read THEN
    NEW.read_at := coalesce(OLD.read_at, now());
  END IF;
  IF NEW.is_read OR NEW.delivered_at IS NOT NULL THEN
    NEW.delivered_at := coalesce(OLD.delivered_at, now());
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.is_chat_participant(_conversation_id uuid)
RETURNS boolean
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT EXISTS (SELECT 1 FROM public.conversations
                 WHERE id = _conversation_id AND auth.uid() IN (buyer_id, seller_id))
$$;

CREATE OR REPLACE FUNCTION public.mark_conversation_delivered(_conversation_id uuid)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  UPDATE public.messages SET delivered_at = now()
  WHERE conversation_id = _conversation_id AND sender_id <> auth.uid() AND delivered_at IS NULL
    AND public.is_chat_participant(_conversation_id)
$$;

CREATE OR REPLACE FUNCTION public.mark_conversation_read(_conversation_id uuid)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  UPDATE public.messages
  SET is_read = true, read_at = coalesce(read_at, now()), delivered_at = coalesce(delivered_at, now())
  WHERE conversation_id = _conversation_id AND sender_id <> auth.uid() AND NOT is_read
    AND public.is_chat_participant(_conversation_id)
$$;

CREATE OR REPLACE FUNCTION public.count_unread_messages()
RETURNS integer
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT count(*)::int FROM public.messages m
  JOIN public.conversations c ON c.id = m.conversation_id
  WHERE auth.uid() IN (c.buyer_id, c.seller_id) AND m.sender_id <> auth.uid()
    AND NOT m.is_read AND m.deleted_at IS NULL
$$;

-- Delete for everyone: your own plain messages only. Returns the attachment path, if any,
-- so the app can remove the file. Offers, quotes, receipts, promises and handover stay.
CREATE OR REPLACE FUNCTION public.delete_my_message(_message_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  m public.messages%ROWTYPE;
BEGIN
  SELECT * INTO m FROM public.messages WHERE id = _message_id FOR UPDATE;
  IF NOT FOUND OR m.sender_id <> auth.uid() THEN RAISE EXCEPTION 'You can only delete your own messages'; END IF;
  IF m.kind <> 'text' THEN RAISE EXCEPTION 'Offers, quotes, receipts and handover records cannot be deleted'; END IF;
  IF m.deleted_at IS NOT NULL THEN RETURN NULL; END IF;
  UPDATE public.messages
  SET content = '', deleted_at = now(), attachment_path = NULL, attachment_type = NULL,
      attachment_name = NULL, attachment_size = NULL, attachment_duration = NULL
  WHERE id = _message_id;
  RETURN m.attachment_path;
END;
$$;

REVOKE ALL ON FUNCTION public.mark_conversation_delivered(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.mark_conversation_read(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.count_unread_messages() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.delete_my_message(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mark_conversation_delivered(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.count_unread_messages() TO authenticated;
GRANT EXECUTE ON FUNCTION public.delete_my_message(uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 3. Reactions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.message_reactions (
  message_id uuid NOT NULL REFERENCES public.messages (id) ON DELETE CASCADE,
  user_id uuid NOT NULL DEFAULT auth.uid(),
  emoji text NOT NULL CHECK (emoji IN ('👍', '❤️', '😂', '😮', '🙏', '👎')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (message_id, user_id)
);

ALTER TABLE public.message_reactions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Participants see reactions" ON public.message_reactions;
DROP POLICY IF EXISTS "Participants see reactions" ON public.message_reactions;
CREATE POLICY "Participants see reactions" ON public.message_reactions
  FOR SELECT USING (EXISTS (SELECT 1 FROM public.messages m WHERE m.id = message_id AND public.is_chat_participant(m.conversation_id)));
DROP POLICY IF EXISTS "Participants react" ON public.message_reactions;
DROP POLICY IF EXISTS "Participants react" ON public.message_reactions;
CREATE POLICY "Participants react" ON public.message_reactions
  FOR INSERT WITH CHECK (user_id = auth.uid()
    AND EXISTS (SELECT 1 FROM public.messages m WHERE m.id = message_id AND m.deleted_at IS NULL AND public.is_chat_participant(m.conversation_id)));
DROP POLICY IF EXISTS "People change their own reaction" ON public.message_reactions;
DROP POLICY IF EXISTS "People change their own reaction" ON public.message_reactions;
CREATE POLICY "People change their own reaction" ON public.message_reactions
  FOR UPDATE USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
DROP POLICY IF EXISTS "People remove their own reaction" ON public.message_reactions;
DROP POLICY IF EXISTS "People remove their own reaction" ON public.message_reactions;
CREATE POLICY "People remove their own reaction" ON public.message_reactions
  FOR DELETE USING (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- 4. Last seen
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_presence (
  user_id uuid PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
  last_seen_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.user_presence ENABLE ROW LEVEL SECURITY;
-- No policies: read and written only through the two functions below.

CREATE OR REPLACE FUNCTION public.touch_presence()
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  INSERT INTO public.user_presence (user_id, last_seen_at) VALUES (auth.uid(), now())
  ON CONFLICT (user_id) DO UPDATE SET last_seen_at = now()
$$;

-- Only the other person in a conversation can see when you were last active.
CREATE OR REPLACE FUNCTION public.get_chat_partner_last_seen(_conversation_id uuid)
RETURNS timestamptz
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT p.last_seen_at FROM public.conversations c
  JOIN public.user_presence p ON p.user_id = CASE WHEN c.buyer_id = auth.uid() THEN c.seller_id ELSE c.buyer_id END
  WHERE c.id = _conversation_id AND auth.uid() IN (c.buyer_id, c.seller_id)
$$;

REVOKE ALL ON FUNCTION public.touch_presence() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.get_chat_partner_last_seen(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.touch_presence() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_chat_partner_last_seen(uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 5. Attachments: a private bucket, one folder per conversation
-- ---------------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('wavechat', 'wavechat', false, 10485760, ARRAY[
  'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf',
  'audio/webm', 'audio/ogg', 'audio/mp4', 'audio/mpeg', 'audio/aac'
])
ON CONFLICT (id) DO NOTHING;

DROP POLICY IF EXISTS "WaveChat participants read attachments" ON storage.objects;
DROP POLICY IF EXISTS "WaveChat participants read attachments" ON storage.objects;
CREATE POLICY "WaveChat participants read attachments" ON storage.objects
  FOR SELECT TO authenticated
  USING (bucket_id = 'wavechat' AND EXISTS (
    SELECT 1 FROM public.conversations c
    WHERE c.id::text = (storage.foldername(name))[1] AND auth.uid() IN (c.buyer_id, c.seller_id)));

DROP POLICY IF EXISTS "WaveChat participants upload attachments" ON storage.objects;
DROP POLICY IF EXISTS "WaveChat participants upload attachments" ON storage.objects;
CREATE POLICY "WaveChat participants upload attachments" ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'wavechat' AND EXISTS (
    SELECT 1 FROM public.conversations c
    WHERE c.id::text = (storage.foldername(name))[1] AND auth.uid() IN (c.buyer_id, c.seller_id)));

DROP POLICY IF EXISTS "WaveChat senders remove their attachments" ON storage.objects;
DROP POLICY IF EXISTS "WaveChat senders remove their attachments" ON storage.objects;
CREATE POLICY "WaveChat senders remove their attachments" ON storage.objects
  FOR DELETE TO authenticated
  USING (bucket_id = 'wavechat' AND owner = auth.uid());

-- ---------------------------------------------------------------------------
-- 6. Receipts for every payment, payment promises, handover
-- ---------------------------------------------------------------------------
ALTER TABLE public.sale_receipts ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'final';
ALTER TABLE public.sale_receipts DROP CONSTRAINT IF EXISTS sale_receipts_kind_check;
ALTER TABLE public.sale_receipts ADD CONSTRAINT sale_receipts_kind_check CHECK (kind IN ('deposit', 'part_payment', 'final'));
DROP INDEX IF EXISTS public.sale_receipts_one_per_conversation;
CREATE UNIQUE INDEX IF NOT EXISTS sale_receipts_one_final_per_conversation ON public.sale_receipts (conversation_id) WHERE kind = 'final';

CREATE TABLE IF NOT EXISTS public.payment_promises (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id uuid NOT NULL REFERENCES public.conversations (id),
  buyer_id uuid NOT NULL,
  seller_id uuid NOT NULL,
  amount numeric NOT NULL CHECK (amount > 0),
  due_date date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  kept_at timestamptz,
  kept_on_time boolean,
  cancelled_at timestamptz
);
CREATE INDEX IF NOT EXISTS idx_payment_promises_conversation ON public.payment_promises (conversation_id);

ALTER TABLE public.payment_promises ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Buyer and seller read promises" ON public.payment_promises;
DROP POLICY IF EXISTS "Buyer and seller read promises" ON public.payment_promises;
CREATE POLICY "Buyer and seller read promises" ON public.payment_promises
  FOR SELECT USING (auth.uid() IN (buyer_id, seller_id) OR public.is_admin());
-- No write policies: promises change only through wavechat_action.

CREATE TABLE IF NOT EXISTS public.handover_items (
  conversation_id uuid NOT NULL REFERENCES public.conversations (id),
  item_key text NOT NULL,
  label text NOT NULL,
  position integer NOT NULL,
  seller_confirmed_at timestamptz,
  buyer_confirmed_at timestamptz,
  PRIMARY KEY (conversation_id, item_key)
);

ALTER TABLE public.handover_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Buyer and seller read handover" ON public.handover_items;
DROP POLICY IF EXISTS "Buyer and seller read handover" ON public.handover_items;
CREATE POLICY "Buyer and seller read handover" ON public.handover_items
  FOR SELECT USING (public.is_chat_participant(conversation_id) OR public.is_admin());
-- No write policies: handover changes only through wavechat_action.

-- Keeping a payment promise on time earns the buyer MID points (PRD: debtor resolved within promise +2)
INSERT INTO public.mid_point_rules (version_id, event_type, points, label)
SELECT id, 'payment_promise_kept', 2, 'Payment promise kept on time'
FROM public.score_config_versions WHERE is_active
ON CONFLICT (version_id, event_type) DO NOTHING;

-- Marks open promises as kept once enough has been paid since each was made.
CREATE OR REPLACE FUNCTION public.settle_payment_promises(_conversation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  p public.payment_promises%ROWTYPE;
  paid numeric;
  on_time boolean;
BEGIN
  FOR p IN SELECT * FROM public.payment_promises
           WHERE conversation_id = _conversation_id AND kept_at IS NULL AND cancelled_at IS NULL LOOP
    SELECT coalesce(sum(amount), 0) INTO paid FROM public.sale_receipts
    WHERE conversation_id = _conversation_id AND issued_at >= p.created_at;
    IF paid >= p.amount THEN
      on_time := (now() AT TIME ZONE 'Africa/Lagos')::date <= p.due_date;
      UPDATE public.payment_promises SET kept_at = now(), kept_on_time = on_time WHERE id = p.id;
      IF on_time THEN
        PERFORM public.award_mid_points(p.buyer_id, 'payment_promise_kept', 'payment_promise_kept:' || p.id, 'payment_promises:' || p.id);
      END IF;
    END IF;
  END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.settle_payment_promises(uuid) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 7. Structured actions (replaces the earlier version, keeping its actions)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.wavechat_action(
  _conversation_id uuid,
  _action text,
  _payload jsonb DEFAULT '{}'::jsonb,
  _client_event_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  me uuid := auth.uid();
  today date := (now() AT TIME ZONE 'Africa/Lagos')::date;
  c public.conversations%ROWTYPE;
  l public.car_listings%ROWTYPE;
  who text;
  existing uuid;
  msg_id uuid;
  amount numeric;
  ref public.messages%ROWTYPE;
  when_at timestamptz;
  due date;
  method text;
  receipt_kind text;
  receipt public.sale_receipts%ROWTYPE;
  promise public.payment_promises%ROWTYPE;
  includes jsonb;
  note text;
  handover_item text;
  body text;
  msg_kind text := 'action';
  msg_payload jsonb;
  new_stage text;
  title text;
  is_foreign boolean;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'Sign in to use WaveChat'; END IF;
  IF public.feature_mode('wavechat') <> 'motorcars' THEN RAISE EXCEPTION 'WaveChat is not available yet'; END IF;

  -- A retried tap returns the message it already created
  IF _client_event_id IS NOT NULL THEN
    SELECT id INTO existing FROM public.messages WHERE client_event_id = _client_event_id;
    IF existing IS NOT NULL THEN RETURN existing; END IF;
  END IF;

  SELECT * INTO c FROM public.conversations WHERE id = _conversation_id FOR UPDATE;
  IF NOT FOUND OR me NOT IN (c.buyer_id, c.seller_id) THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  who := CASE WHEN me = c.seller_id THEN 'seller' ELSE 'buyer' END;
  new_stage := c.stage;

  SELECT * INTO l FROM public.car_listings WHERE id = c.listing_id;
  title := concat_ws(' ', l.year, l.make, l.model);

  -- Who may do what
  IF _action IN ('ask_availability', 'request_photos', 'book_inspection', 'make_offer', 'withdraw_offer',
                 'accept_quote', 'request_quote_changes', 'promise_payment', 'confirm_receipt')
     AND who <> 'buyer' THEN
    RAISE EXCEPTION 'Only the buyer can do that';
  END IF;
  IF _action IN ('confirm_available', 'reply_not_available', 'confirm_inspection', 'accept_offer', 'decline_offer',
                 'send_quote', 'record_payment', 'record_sale', 'start_handover')
     AND who <> 'seller' THEN
    RAISE EXCEPTION 'Only the seller can do that';
  END IF;

  -- When: after the final payment only handover and receipt confirmation remain; after handover, only confirmations
  IF c.stage = 'closed' THEN RAISE EXCEPTION 'This conversation is closed'; END IF;
  IF c.stage = 'completed' AND _action <> 'confirm_receipt' THEN RAISE EXCEPTION 'This sale is complete'; END IF;
  IF c.stage = 'paid' AND _action NOT IN ('start_handover', 'confirm_handover_item', 'confirm_receipt') THEN
    RAISE EXCEPTION 'The car has been paid for; only handover steps remain';
  END IF;

  IF _action = 'ask_availability' THEN
    body := 'Is this car still available?';

  ELSIF _action = 'confirm_available' THEN
    IF l.availability_status <> 'available' THEN
      RAISE EXCEPTION 'This car is not marked available. Update its status first.';
    END IF;
    UPDATE public.car_listings SET availability_confirmed_at = now() WHERE id = l.id;
    body := 'Yes, it''s still available.';

  ELSIF _action = 'reply_not_available' THEN
    body := 'Sorry, this car is no longer available.';

  ELSIF _action = 'request_photos' THEN
    body := 'Could you send more photos, including the engine bay, the interior and any damage?';

  ELSIF _action = 'book_inspection' THEN
    when_at := (_payload ->> 'proposed_at')::timestamptz;
    IF when_at IS NULL OR when_at < now() THEN RAISE EXCEPTION 'Choose a time in the future for the inspection'; END IF;
    UPDATE public.conversations SET inspection_at = when_at, inspection_confirmed = false WHERE id = c.id;
    body := 'I''d like to inspect the car on ' || to_char(when_at AT TIME ZONE 'Africa/Lagos', 'FMDay DD Mon, HH12:MI AM') || '.';
    msg_payload := jsonb_build_object('proposed_at', when_at);
    IF c.stage = 'enquiry' THEN new_stage := 'inspection'; END IF;

  ELSIF _action = 'confirm_inspection' THEN
    IF c.inspection_at IS NULL THEN RAISE EXCEPTION 'The buyer has not asked for an inspection yet'; END IF;
    UPDATE public.conversations SET inspection_confirmed = true WHERE id = c.id;
    body := 'Inspection confirmed for ' || to_char(c.inspection_at AT TIME ZONE 'Africa/Lagos', 'FMDay DD Mon, HH12:MI AM') || '.';
    msg_payload := jsonb_build_object('inspection_at', c.inspection_at);

  ELSIF _action = 'make_offer' THEN
    IF c.stage = 'agreed' THEN RAISE EXCEPTION 'A price is already agreed'; END IF;
    amount := round((_payload ->> 'amount')::numeric);
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter an offer above zero'; END IF;
    UPDATE public.messages SET payload = payload || '{"status":"replaced"}'
    WHERE conversation_id = c.id AND kind = 'offer' AND payload ->> 'status' = 'pending';
    msg_kind := 'offer';
    msg_payload := jsonb_build_object('amount', amount, 'status', 'pending');
    body := 'Offer: ' || public.naira(amount) || '. An offer in chat is not a sale or a payment.';
    IF c.stage IN ('enquiry', 'inspection') THEN new_stage := 'offer'; END IF;

  ELSIF _action IN ('accept_offer', 'decline_offer', 'withdraw_offer') THEN
    SELECT * INTO ref FROM public.messages
    WHERE id = (_payload ->> 'offer_id')::uuid AND conversation_id = c.id AND kind = 'offer' FOR UPDATE;
    IF NOT FOUND OR ref.payload ->> 'status' <> 'pending' THEN RAISE EXCEPTION 'That offer is no longer open'; END IF;
    amount := (ref.payload ->> 'amount')::numeric;
    UPDATE public.messages
    SET payload = payload || jsonb_build_object('status',
      CASE _action WHEN 'accept_offer' THEN 'accepted' WHEN 'decline_offer' THEN 'declined' ELSE 'withdrawn' END)
    WHERE id = ref.id;
    msg_kind := 'offer_response';
    msg_payload := jsonb_build_object('offer_id', ref.id, 'amount', amount);
    IF _action = 'accept_offer' THEN
      UPDATE public.conversations SET agreed_price = amount WHERE id = c.id;
      new_stage := 'agreed';
      body := 'Offer of ' || public.naira(amount) || ' accepted. This is an agreement in chat, not a sale or a payment.';
    ELSIF _action = 'decline_offer' THEN
      body := 'Offer of ' || public.naira(amount) || ' declined.';
    ELSE
      body := 'Offer of ' || public.naira(amount) || ' withdrawn.';
    END IF;

  ELSIF _action = 'send_quote' THEN
    IF c.stage = 'agreed' THEN RAISE EXCEPTION 'A price is already agreed'; END IF;
    amount := round((_payload ->> 'amount')::numeric);
    due := (_payload ->> 'valid_until')::date;
    includes := coalesce(_payload -> 'includes', '[]'::jsonb);
    note := left(btrim(coalesce(_payload ->> 'note', '')), 300);
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter the quoted price'; END IF;
    IF due IS NULL OR due < today THEN RAISE EXCEPTION 'Choose a valid-until date from today on'; END IF;
    IF jsonb_typeof(includes) <> 'array' OR jsonb_array_length(includes) > 10 THEN RAISE EXCEPTION 'List up to 10 included items'; END IF;
    UPDATE public.messages SET payload = payload || '{"status":"replaced"}'
    WHERE conversation_id = c.id AND kind = 'quote' AND payload ->> 'status' = 'pending';
    msg_kind := 'quote';
    msg_payload := jsonb_build_object('amount', amount, 'valid_until', due, 'includes', includes, 'note', nullif(note, ''), 'status', 'pending');
    body := 'Quote: ' || public.naira(amount) || ', valid until ' || to_char(due, 'FMDD Mon YYYY') || '.';
    IF c.stage IN ('enquiry', 'inspection') THEN new_stage := 'offer'; END IF;

  ELSIF _action IN ('accept_quote', 'request_quote_changes') THEN
    SELECT * INTO ref FROM public.messages
    WHERE id = (_payload ->> 'quote_id')::uuid AND conversation_id = c.id AND kind = 'quote' FOR UPDATE;
    IF NOT FOUND OR ref.payload ->> 'status' <> 'pending' THEN RAISE EXCEPTION 'That quote is no longer open'; END IF;
    amount := (ref.payload ->> 'amount')::numeric;
    msg_kind := 'quote_response';
    msg_payload := jsonb_build_object('quote_id', ref.id, 'amount', amount);
    IF _action = 'accept_quote' THEN
      IF (ref.payload ->> 'valid_until')::date < today THEN RAISE EXCEPTION 'This quote has expired. Ask the seller for a new one.'; END IF;
      UPDATE public.messages SET payload = payload || '{"status":"accepted"}' WHERE id = ref.id;
      UPDATE public.conversations SET agreed_price = amount WHERE id = c.id;
      new_stage := 'agreed';
      body := 'Quote of ' || public.naira(amount) || ' accepted. This is an agreement in chat, not a sale or a payment.';
    ELSE
      note := left(btrim(coalesce(_payload ->> 'note', '')), 300);
      UPDATE public.messages SET payload = payload || '{"status":"changes_requested"}' WHERE id = ref.id;
      msg_payload := msg_payload || jsonb_build_object('note', nullif(note, ''));
      body := 'Could you change the quote?' || CASE WHEN note <> '' THEN ' ' || note ELSE '' END;
    END IF;

  ELSIF _action = 'promise_payment' THEN
    amount := round((_payload ->> 'amount')::numeric);
    due := (_payload ->> 'due_date')::date;
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter the amount you will pay'; END IF;
    IF due IS NULL OR due < today THEN RAISE EXCEPTION 'Choose a date from today on'; END IF;
    -- A new promise replaces any promise still open
    UPDATE public.payment_promises SET cancelled_at = now()
    WHERE conversation_id = c.id AND kept_at IS NULL AND cancelled_at IS NULL;
    INSERT INTO public.payment_promises (conversation_id, buyer_id, seller_id, amount, due_date)
    VALUES (c.id, c.buyer_id, c.seller_id, amount, due) RETURNING * INTO promise;
    msg_kind := 'promise';
    msg_payload := jsonb_build_object('promise_id', promise.id, 'amount', amount, 'due_date', due);
    body := 'I will pay ' || public.naira(amount) || ' by ' || to_char(due, 'FMDay DD Mon') || '.';

  ELSIF _action IN ('record_payment', 'record_sale') THEN
    amount := round((_payload ->> 'amount')::numeric);
    method := _payload ->> 'payment_method';
    IF amount IS NULL OR amount <= 0 THEN RAISE EXCEPTION 'Enter the amount paid'; END IF;
    IF method IS NULL OR method NOT IN ('cash', 'bank_transfer', 'pos', 'ussd', 'other') THEN
      RAISE EXCEPTION 'Choose how the buyer paid';
    END IF;
    IF _action = 'record_sale' THEN
      IF l.availability_status = 'sold' THEN RAISE EXCEPTION 'This car is already marked sold'; END IF;
      receipt_kind := 'final';
    ELSE
      receipt_kind := CASE WHEN _payload ->> 'kind' = 'part_payment' THEN 'part_payment' ELSE 'deposit' END;
    END IF;

    INSERT INTO public.sale_receipts (receipt_number, conversation_id, listing_id, buyer_id, seller_id, car_title, amount, payment_method, kind)
    VALUES ('MC-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.sale_receipt_number_seq')::text, 6, '0'),
            c.id, l.id, c.buyer_id, c.seller_id, title, amount, method, receipt_kind)
    RETURNING * INTO receipt;
    PERFORM public.award_mid_points(c.seller_id, 'receipt_sent', 'receipt_sent:' || receipt.id, 'sale_receipts:' || receipt.id);
    PERFORM public.settle_payment_promises(c.id);

    msg_kind := 'receipt';
    msg_payload := jsonb_build_object('receipt_id', receipt.id, 'receipt_number', receipt.receipt_number, 'amount', amount,
                                      'payment_method', method, 'kind', receipt_kind);
    IF _action = 'record_sale' THEN
      -- The car is sold: Open Inventory records it and the seller's MID gets the sale points
      UPDATE public.car_listings SET availability_status = 'sold' WHERE id = l.id;
      body := 'Final payment recorded: ' || public.naira(amount) || '. Receipt ' || receipt.receipt_number || '. The car is marked sold.';
      -- If the handover was already completed, the sale is now complete
      new_stage := CASE WHEN EXISTS (SELECT 1 FROM public.handover_items WHERE conversation_id = c.id)
                         AND NOT EXISTS (SELECT 1 FROM public.handover_items
                                         WHERE conversation_id = c.id AND (seller_confirmed_at IS NULL OR buyer_confirmed_at IS NULL))
                        THEN 'completed' ELSE 'paid' END;
    ELSE
      body := CASE receipt_kind WHEN 'deposit' THEN 'Deposit' ELSE 'Part payment' END
              || ' recorded: ' || public.naira(amount) || '. Receipt ' || receipt.receipt_number || '.';
    END IF;

  ELSIF _action = 'confirm_receipt' THEN
    UPDATE public.sale_receipts SET buyer_confirmed_at = now()
    WHERE id = (_payload ->> 'receipt_id')::uuid AND conversation_id = c.id AND buyer_id = me AND buyer_confirmed_at IS NULL
    RETURNING * INTO receipt;
    IF receipt.id IS NULL THEN RAISE EXCEPTION 'There is no receipt to confirm'; END IF;
    msg_payload := jsonb_build_object('receipt_id', receipt.id);
    body := 'I confirm receipt ' || receipt.receipt_number || ' is correct.';

  ELSIF _action = 'start_handover' THEN
    IF c.stage NOT IN ('agreed', 'paid') THEN RAISE EXCEPTION 'Agree a price before starting the handover'; END IF;
    IF EXISTS (SELECT 1 FROM public.handover_items WHERE conversation_id = c.id) THEN
      RAISE EXCEPTION 'The handover checklist has already been started';
    END IF;
    is_foreign := lower(replace(coalesce(l.condition, ''), '-', '_')) IN ('foreign_used', 'tokunbo', 'foreign used');
    INSERT INTO public.handover_items (conversation_id, item_key, label, position) VALUES
      (c.id, 'ownership', 'Proof of ownership (purchase receipt or change of ownership)', 1),
      (c.id, 'licence', 'Vehicle licence', 2),
      (c.id, 'roadworthiness', 'Roadworthiness certificate', 3),
      (c.id, 'insurance', 'Insurance certificate', 5),
      (c.id, 'keys', 'All keys, including the spare', 6),
      (c.id, 'car', 'Car handed over to the buyer', 7);
    IF is_foreign THEN
      INSERT INTO public.handover_items (conversation_id, item_key, label, position)
      VALUES (c.id, 'customs', 'Customs duty papers', 4);
    END IF;
    msg_kind := 'handover';
    msg_payload := jsonb_build_object('status', 'started');
    body := 'Handover checklist started. Tick each item as it is handed over; both of us confirm.';

  ELSIF _action = 'confirm_handover_item' THEN
    handover_item := _payload ->> 'item';
    IF who = 'seller' THEN
      UPDATE public.handover_items SET seller_confirmed_at = now()
      WHERE conversation_id = c.id AND handover_items.item_key = handover_item AND seller_confirmed_at IS NULL;
    ELSE
      UPDATE public.handover_items SET buyer_confirmed_at = now()
      WHERE conversation_id = c.id AND handover_items.item_key = handover_item AND buyer_confirmed_at IS NULL;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'That item is already confirmed or is not on the checklist'; END IF;
    UPDATE public.conversations SET updated_at = now() WHERE id = c.id;

    -- Only the completing tick leaves a message; the checklist itself shows each tick
    IF NOT EXISTS (SELECT 1 FROM public.handover_items
                   WHERE conversation_id = c.id AND (seller_confirmed_at IS NULL OR buyer_confirmed_at IS NULL)) THEN
      msg_kind := 'handover';
      msg_payload := jsonb_build_object('status', 'complete');
      body := 'Handover complete: both of us have confirmed every item.';
      IF EXISTS (SELECT 1 FROM public.sale_receipts WHERE conversation_id = c.id AND kind = 'final') THEN
        new_stage := 'completed';
      END IF;
    ELSE
      RETURN NULL;
    END IF;

  ELSE
    RAISE EXCEPTION 'Unknown WaveChat action %', _action;
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, kind, action, payload, client_event_id)
  VALUES (c.id, me, body, msg_kind, _action, msg_payload, _client_event_id)
  RETURNING id INTO msg_id;

  UPDATE public.conversations SET stage = new_stage, updated_at = now() WHERE id = c.id;
  RETURN msg_id;
END;
$$;
REVOKE ALL ON FUNCTION public.wavechat_action(uuid, text, jsonb, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.wavechat_action(uuid, text, jsonb, uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 8. Live updates
-- ---------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    FOREACH t IN ARRAY ARRAY['messages', 'conversations', 'message_reactions', 'handover_items'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                     WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
      END IF;
    END LOOP;
  END IF;
END $$;

COMMIT;


-- ===== 20261109120000_conscience.sql =====
-- Conscience Protocol, interim Motorcars version.
-- Requires, in order: 20261021120000_security_hardening.sql, 20261029120000_listing_lifecycle.sql,
-- 20261105120000_platform_features_and_mid.sql, 20261106120000_open_inventory.sql,
-- 20261107120000_wavechat.sql, 20261108120000_wavechat_conversation_features.sql.
--
-- Each seller with live cars runs 14-day cycles: 12 days observed, then 48 hours to reconcile, then
-- sealed for good. Findings come only from records Motorcars already keeps:
-- * not_confirmed: a live car with no confirmation or stock update during the 12 days
-- * chat_says_unavailable: the seller told a buyer the car is gone, but it is still listed available
-- * paid_still_available: a deposit or part payment was recorded, but the car is still listed available
-- * availability_lie: an admin upheld a buyer's report that a car shown available was already sold.
--   Nothing automatic can prove a lie, so a person decides from the evidence.
-- Points (values in mid_point_rules, seeded in 20261105120000): a clean cycle earns clean_cycle, and
-- two clean cycles sealed in one month earn two_clean_cycles_month. Unreconciled contradictions cost
-- unreconciled_mismatch per car; forgotten confirmations cost it once per cycle however many cars;
-- each upheld lie costs availability_lie. Cycles with no cars earn and cost nothing.
-- Cycles advance through conscience_run(), hourly where pg_cron is available, and whenever a
-- seller opens their record. Sealed cycles and their findings can never be changed.
-- Adds tables and functions only; no existing row is changed or deleted.
-- Reverse with supabase/rollback/20261109120000_conscience_down.sql.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Cycles and findings
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.conscience_cycles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Not a foreign key on purpose: a sealed record outlives the account
  seller_id uuid NOT NULL,
  cycle_number integer NOT NULL,
  status text NOT NULL DEFAULT 'observing' CHECK (status IN ('observing', 'reconciling', 'sealed')),
  starts_at timestamptz NOT NULL DEFAULT now(),
  observation_ends_at timestamptz NOT NULL DEFAULT now() + interval '12 days',
  reconcile_ends_at timestamptz NOT NULL DEFAULT now() + interval '14 days',
  cars_tracked integer NOT NULL DEFAULT 0,
  cars_confirmed integer NOT NULL DEFAULT 0,
  outcome text CHECK (outcome IN ('clean', 'flagged', 'quiet')),
  points_awarded numeric(6, 2) NOT NULL DEFAULT 0,
  sealed_at timestamptz,
  -- Set once the sealed cycle has been sent to Moatwave
  synced_to_moatwave_at timestamptz,
  UNIQUE (seller_id, cycle_number)
);
CREATE UNIQUE INDEX IF NOT EXISTS conscience_one_open_cycle ON public.conscience_cycles (seller_id) WHERE status <> 'sealed';

CREATE TABLE IF NOT EXISTS public.conscience_findings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cycle_id uuid NOT NULL REFERENCES public.conscience_cycles (id),
  seller_id uuid NOT NULL,
  -- Not a foreign key on purpose: findings outlive a deleted listing
  listing_id uuid NOT NULL,
  car_title text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('not_confirmed', 'chat_says_unavailable', 'paid_still_available', 'availability_lie')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reconciled', 'unreconciled', 'upheld')),
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  opened_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  UNIQUE (cycle_id, listing_id, kind)
);
CREATE INDEX IF NOT EXISTS idx_conscience_findings_seller ON public.conscience_findings (seller_id, opened_at DESC);

ALTER TABLE public.conscience_cycles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.conscience_findings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Sellers read their own cycles" ON public.conscience_cycles;
DROP POLICY IF EXISTS "Sellers read their own cycles" ON public.conscience_cycles;
CREATE POLICY "Sellers read their own cycles" ON public.conscience_cycles
  FOR SELECT USING (auth.uid() = seller_id OR public.is_admin());
DROP POLICY IF EXISTS "Sellers read their own findings" ON public.conscience_findings;
DROP POLICY IF EXISTS "Sellers read their own findings" ON public.conscience_findings;
CREATE POLICY "Sellers read their own findings" ON public.conscience_findings
  FOR SELECT USING (auth.uid() = seller_id OR public.is_admin());
-- No write policies: only the functions below change cycles and findings.

CREATE OR REPLACE FUNCTION public.keep_conscience_cycles()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status <> 'sealed' THEN RETURN NEW; END IF;
  -- The only change to a sealed cycle is marking it as sent to Moatwave
  IF TG_OP = 'UPDATE'
     AND (to_jsonb(NEW) - 'synced_to_moatwave_at') = (to_jsonb(OLD) - 'synced_to_moatwave_at') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Conscience cycles cannot be deleted, and sealed cycles cannot be changed';
END;
$$;

DROP TRIGGER IF EXISTS keep_conscience_cycles ON public.conscience_cycles;
CREATE TRIGGER keep_conscience_cycles
  BEFORE UPDATE OR DELETE ON public.conscience_cycles
  FOR EACH ROW EXECUTE FUNCTION public.keep_conscience_cycles();

CREATE OR REPLACE FUNCTION public.keep_conscience_findings()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT EXISTS (
    SELECT 1 FROM public.conscience_cycles WHERE id = OLD.cycle_id AND status = 'sealed') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Conscience findings cannot be deleted, and sealed findings cannot be changed';
END;
$$;

DROP TRIGGER IF EXISTS keep_conscience_findings ON public.conscience_findings;
CREATE TRIGGER keep_conscience_findings
  BEFORE UPDATE OR DELETE ON public.conscience_findings
  FOR EACH ROW EXECUTE FUNCTION public.keep_conscience_findings();

-- ---------------------------------------------------------------------------
-- 2. Moving a seller's cycle forward
-- ---------------------------------------------------------------------------
-- Whether a finding has been put right. A car that has left the live stock has nothing to reconcile.
CREATE OR REPLACE FUNCTION public.conscience_finding_cleared(_finding public.conscience_findings, _observation_ends_at timestamptz)
RETURNS boolean
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT NOT EXISTS (
      SELECT 1 FROM public.car_listings l
      WHERE l.id = _finding.listing_id AND l.status = 'active'
        AND l.availability_status IN ('available', 'reserved'))
    OR CASE _finding.kind
      WHEN 'not_confirmed' THEN EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = _finding.listing_id AND e.occurred_at > _observation_ends_at
          AND e.event_type IN ('availability_confirmed', 'made_available', 'reserved', 'renewed'))
      WHEN 'chat_says_unavailable' THEN EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = _finding.listing_id AND e.occurred_at > (_finding.evidence ->> 'said_at')::timestamptz
          AND e.event_type IN ('availability_confirmed', 'made_available', 'reserved'))
      -- Confirming isn't enough here: the car has to be reserved, or put back on sale after a refund
      WHEN 'paid_still_available' THEN EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = _finding.listing_id AND e.occurred_at > (_finding.evidence ->> 'paid_at')::timestamptz
          AND e.event_type IN ('made_available', 'reserved'))
      ELSE false
    END
$$;
REVOKE ALL ON FUNCTION public.conscience_finding_cleared(public.conscience_findings, timestamptz) FROM PUBLIC, anon, authenticated;

-- Internal: takes one step if one is due. Safe to call at any time and any number of times.
CREATE OR REPLACE FUNCTION public.conscience_advance(_seller_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  c public.conscience_cycles%ROWTYPE;
  f public.conscience_findings%ROWTYPE;
  tracked integer;
  confirmed integer;
  open_count integer;
  missed integer := 0;
  against integer := 0;
  earned numeric := 0;
  verdict text;
  month_label text;
BEGIN
  IF _seller_id IS NULL OR public.feature_mode('conscience') <> 'motorcars' THEN RETURN; END IF;

  SELECT * INTO c FROM public.conscience_cycles WHERE seller_id = _seller_id AND status <> 'sealed' FOR UPDATE;

  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.car_listings WHERE user_id = _seller_id AND status = 'active'
               AND availability_status IN ('available', 'reserved')) THEN
      INSERT INTO public.conscience_cycles (seller_id, cycle_number)
      SELECT _seller_id, coalesce(max(cycle_number), 0) + 1 FROM public.conscience_cycles WHERE seller_id = _seller_id;
    END IF;
    RETURN;
  END IF;

  -- Day 12: compare the listings with what was recorded, and open the 48-hour window
  IF c.status = 'observing' AND now() >= c.observation_ends_at THEN
    SELECT count(*), count(*) FILTER (WHERE EXISTS (
             SELECT 1 FROM public.inventory_events e
             WHERE e.listing_id = l.id AND e.occurred_at >= c.starts_at AND NOT e.backfilled
               AND e.event_type IN ('availability_confirmed', 'made_available', 'reserved', 'listed', 'renewed')))
    INTO tracked, confirmed
    FROM public.car_listings l
    WHERE l.user_id = _seller_id AND l.status = 'active' AND l.availability_status IN ('available', 'reserved');

    INSERT INTO public.conscience_findings (cycle_id, seller_id, listing_id, car_title, kind, evidence)
    SELECT c.id, _seller_id, l.id, concat_ws(' ', l.year, l.make, l.model), 'not_confirmed',
           jsonb_build_object('last_confirmed_at', l.availability_confirmed_at)
    FROM public.car_listings l
    WHERE l.user_id = _seller_id AND l.status = 'active' AND l.availability_status IN ('available', 'reserved')
      AND NOT EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = l.id AND e.occurred_at >= c.starts_at AND NOT e.backfilled
          AND e.event_type IN ('availability_confirmed', 'made_available', 'reserved', 'listed', 'renewed'))
    ON CONFLICT (cycle_id, listing_id, kind) DO NOTHING;

    INSERT INTO public.conscience_findings (cycle_id, seller_id, listing_id, car_title, kind, evidence)
    SELECT c.id, _seller_id, l.id, concat_ws(' ', l.year, l.make, l.model), 'chat_says_unavailable',
           jsonb_build_object('said_at', s.said_at)
    FROM public.car_listings l
    CROSS JOIN LATERAL (
      SELECT max(m.created_at) AS said_at FROM public.messages m
      JOIN public.conversations v ON v.id = m.conversation_id
      WHERE v.listing_id = l.id AND m.sender_id = _seller_id
        AND m.action = 'reply_not_available' AND m.created_at >= c.starts_at
    ) s
    WHERE l.user_id = _seller_id AND l.status = 'active' AND l.availability_status = 'available'
      AND s.said_at IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = l.id AND e.occurred_at > s.said_at
          AND e.event_type IN ('availability_confirmed', 'made_available', 'reserved'))
    ON CONFLICT (cycle_id, listing_id, kind) DO NOTHING;

    INSERT INTO public.conscience_findings (cycle_id, seller_id, listing_id, car_title, kind, evidence)
    SELECT c.id, _seller_id, l.id, concat_ws(' ', l.year, l.make, l.model), 'paid_still_available',
           jsonb_build_object('paid_at', r.issued_at, 'receipt_number', r.receipt_number, 'receipt_kind', r.kind)
    FROM public.car_listings l
    CROSS JOIN LATERAL (
      SELECT sr.issued_at, sr.receipt_number, sr.kind FROM public.sale_receipts sr
      WHERE sr.listing_id = l.id AND sr.seller_id = _seller_id
        AND sr.kind IN ('deposit', 'part_payment') AND sr.issued_at >= c.starts_at
      ORDER BY sr.issued_at DESC LIMIT 1
    ) r
    WHERE l.user_id = _seller_id AND l.status = 'active' AND l.availability_status = 'available'
      AND NOT EXISTS (
        SELECT 1 FROM public.inventory_events e
        WHERE e.listing_id = l.id AND e.occurred_at > r.issued_at AND e.event_type IN ('made_available', 'reserved'))
    ON CONFLICT (cycle_id, listing_id, kind) DO NOTHING;

    -- A late run must still leave the seller their full 48 hours
    UPDATE public.conscience_cycles
    SET status = 'reconciling', cars_tracked = tracked, cars_confirmed = confirmed,
        reconcile_ends_at = greatest(reconcile_ends_at, now() + interval '48 hours')
    WHERE id = c.id;

    SELECT count(*) INTO open_count FROM public.conscience_findings WHERE cycle_id = c.id AND status = 'open';
    IF open_count > 0 THEN
      PERFORM public.create_notification(_seller_id, 'Your Conscience cycle needs attention',
        open_count || CASE WHEN open_count = 1 THEN ' item needs' ELSE ' items need' END
          || ' fixing within 48 hours, before this cycle is sealed for good.',
        'warning', jsonb_build_object('conscience_cycle_id', c.id));
    END IF;
    RETURN;
  END IF;

  -- During the window, show a seller what they've already put right
  IF c.status = 'reconciling' THEN
    FOR f IN SELECT * FROM public.conscience_findings WHERE cycle_id = c.id AND status = 'open' LOOP
      IF public.conscience_finding_cleared(f, c.observation_ends_at) THEN
        UPDATE public.conscience_findings SET status = 'reconciled', closed_at = now() WHERE id = f.id;
      END IF;
    END LOOP;
  END IF;

  -- Day 14: settle what's left, award and deduct points, and seal
  IF c.status = 'reconciling' AND now() >= c.reconcile_ends_at THEN
    FOR f IN SELECT * FROM public.conscience_findings WHERE cycle_id = c.id AND status = 'open' LOOP
      UPDATE public.conscience_findings SET status = 'unreconciled', closed_at = now() WHERE id = f.id;
      IF f.kind = 'not_confirmed' THEN
        missed := missed + 1;
      ELSE
        against := against + 1;
        earned := earned + public.award_mid_points(_seller_id, 'unreconciled_mismatch',
          'unreconciled_mismatch:' || f.id, 'conscience_findings:' || f.id);
      END IF;
    END LOOP;

    -- Forgotten confirmations aren't contradictions: one deduction per cycle however many cars
    IF missed > 0 THEN
      earned := earned + public.award_mid_points(_seller_id, 'unreconciled_mismatch',
        'unreconciled_mismatch:' || c.id || ':not_confirmed', 'conscience_cycles:' || c.id);
    END IF;

    FOR f IN SELECT * FROM public.conscience_findings WHERE cycle_id = c.id AND status = 'upheld' LOOP
      against := against + 1;
      earned := earned + public.award_mid_points(_seller_id, 'availability_lie',
        'availability_lie:' || f.id, 'conscience_findings:' || f.id);
    END LOOP;

    verdict := CASE
      WHEN missed > 0 OR against > 0 THEN 'flagged'
      WHEN c.cars_tracked = 0 THEN 'quiet'
      ELSE 'clean'
    END;

    IF verdict = 'clean' THEN
      earned := earned + public.award_mid_points(_seller_id, 'clean_cycle', 'clean_cycle:' || c.id, 'conscience_cycles:' || c.id);
      month_label := to_char(now() AT TIME ZONE 'Africa/Lagos', 'YYYY-MM');
      IF EXISTS (SELECT 1 FROM public.conscience_cycles
                 WHERE seller_id = _seller_id AND outcome = 'clean'
                   AND to_char(sealed_at AT TIME ZONE 'Africa/Lagos', 'YYYY-MM') = month_label) THEN
        earned := earned + public.award_mid_points(_seller_id, 'two_clean_cycles_month',
          'two_clean_cycles_month:' || _seller_id || ':' || month_label, 'conscience_cycles:' || c.id);
      END IF;
    END IF;

    UPDATE public.conscience_cycles
    SET status = 'sealed', outcome = verdict, points_awarded = earned, sealed_at = now()
    WHERE id = c.id;

    IF verdict <> 'quiet' THEN
      PERFORM public.create_notification(_seller_id,
        CASE verdict WHEN 'clean' THEN 'Clean Conscience cycle sealed' ELSE 'Conscience cycle sealed with problems' END,
        'Cycle ' || c.cycle_number || ' is sealed for good. See your record for the details.',
        CASE verdict WHEN 'clean' THEN 'success' ELSE 'warning' END,
        jsonb_build_object('conscience_cycle_id', c.id));
    END IF;

    -- The next cycle starts straight away if there are still live cars
    PERFORM public.conscience_advance(_seller_id);
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.conscience_advance(uuid) FROM PUBLIC, anon, authenticated;

-- A seller opening their record moves their own cycle on, so nothing waits on the hourly run.
CREATE OR REPLACE FUNCTION public.refresh_my_conscience()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to see your Conscience record'; END IF;
  PERFORM public.conscience_advance(auth.uid());
END;
$$;
REVOKE ALL ON FUNCTION public.refresh_my_conscience() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.refresh_my_conscience() TO authenticated;

-- Moves every seller on. Run by the hourly job (no signed-in user) or by an admin.
CREATE OR REPLACE FUNCTION public.conscience_run()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  seller uuid;
  sellers integer := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only admins can run Conscience cycles';
  END IF;
  FOR seller IN
    SELECT user_id FROM public.car_listings WHERE status = 'active' AND user_id IS NOT NULL
    UNION
    SELECT seller_id FROM public.conscience_cycles WHERE status <> 'sealed'
  LOOP
    PERFORM public.conscience_advance(seller);
    sellers := sellers + 1;
  END LOOP;
  RETURN sellers;
END;
$$;
REVOKE ALL ON FUNCTION public.conscience_run() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.conscience_run() TO authenticated;

-- ---------------------------------------------------------------------------
-- 3. Upholding a report as an availability lie
-- ---------------------------------------------------------------------------
-- Only a person can call something a lie. An admin who has checked a buyer's report records it here;
-- the deduction lands when the seller's current cycle seals.
CREATE OR REPLACE FUNCTION public.conscience_uphold_report(_report_id uuid, _note text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  r public.listing_reports%ROWTYPE;
  l public.car_listings%ROWTYPE;
  cycle uuid;
  finding uuid;
  note text := left(btrim(coalesce(_note, '')), 500);
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Only admins can uphold a report'; END IF;
  IF public.feature_mode('conscience') <> 'motorcars' THEN RAISE EXCEPTION 'Conscience is not switched on'; END IF;

  SELECT * INTO r FROM public.listing_reports WHERE id = _report_id FOR UPDATE;
  IF NOT FOUND OR r.status <> 'open' THEN RAISE EXCEPTION 'That report is no longer open'; END IF;
  IF r.reason <> 'sold_or_unavailable' THEN
    RAISE EXCEPTION 'Only a report that the car is sold or unavailable can be upheld as an availability lie';
  END IF;
  IF note = '' THEN RAISE EXCEPTION 'Write down the evidence you checked'; END IF;

  SELECT * INTO l FROM public.car_listings WHERE id = r.listing_id;
  IF l.user_id IS NULL THEN RAISE EXCEPTION 'This listing has no seller account'; END IF;

  PERFORM public.conscience_advance(l.user_id);
  SELECT id INTO cycle FROM public.conscience_cycles WHERE seller_id = l.user_id AND status <> 'sealed';
  IF cycle IS NULL THEN
    INSERT INTO public.conscience_cycles (seller_id, cycle_number)
    SELECT l.user_id, coalesce(max(cycle_number), 0) + 1 FROM public.conscience_cycles WHERE seller_id = l.user_id
    RETURNING id INTO cycle;
  END IF;

  INSERT INTO public.conscience_findings (cycle_id, seller_id, listing_id, car_title, kind, status, evidence, closed_at)
  VALUES (cycle, l.user_id, l.id, concat_ws(' ', l.year, l.make, l.model), 'availability_lie', 'upheld',
          jsonb_build_object('report_id', r.id, 'reported_at', r.created_at, 'note', note), now())
  ON CONFLICT (cycle_id, listing_id, kind) DO NOTHING
  RETURNING id INTO finding;

  UPDATE public.listing_reports
  SET status = 'resolved', resolved_at = now(), resolved_by = auth.uid(), admin_notes = note
  WHERE id = r.id;

  IF finding IS NOT NULL THEN
    PERFORM public.create_notification(l.user_id, 'A report about your car was upheld',
      'Motorcars checked a report that your ' || concat_ws(' ', l.year, l.make, l.model)
        || ' was shown available after it had gone. This is on your Conscience record.',
      'warning', jsonb_build_object('conscience_finding_id', finding));
  END IF;
  RETURN finding;
END;
$$;
REVOKE ALL ON FUNCTION public.conscience_uphold_report(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.conscience_uphold_report(uuid, text) TO authenticated;

-- ---------------------------------------------------------------------------
-- 4. Reading
-- ---------------------------------------------------------------------------
-- What buyers see: how many cycles were sealed and how many were clean. Findings stay private.
-- Cycles with no cars prove nothing, so they don't count.
CREATE OR REPLACE FUNCTION public.get_public_conscience(_seller_id uuid)
RETURNS TABLE (cycles_sealed integer, clean_cycles integer, last_sealed_at timestamptz, cycle_in_progress boolean)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    (SELECT count(*)::int FROM public.conscience_cycles WHERE seller_id = _seller_id AND outcome IN ('clean', 'flagged')),
    (SELECT count(*)::int FROM public.conscience_cycles WHERE seller_id = _seller_id AND outcome = 'clean'),
    (SELECT max(sealed_at) FROM public.conscience_cycles WHERE seller_id = _seller_id AND outcome IN ('clean', 'flagged')),
    EXISTS (SELECT 1 FROM public.conscience_cycles WHERE seller_id = _seller_id AND status <> 'sealed')
  WHERE public.feature_mode('conscience') = 'motorcars'
$$;
GRANT EXECUTE ON FUNCTION public.get_public_conscience(uuid) TO anon, authenticated;

-- Sealed cycles are now real, so the MID ring can show them as notches
CREATE OR REPLACE FUNCTION public.get_public_mid(_user_id uuid)
RETURNS TABLE (mid text, score numeric, tier text, phone_verified boolean, issued_by text, cycles_sealed integer)
LANGUAGE sql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT CASE
           WHEN m.user_id = auth.uid()
             OR coalesce(p.show_phone_number, false)
             OR EXISTS (SELECT 1 FROM public.dealers d WHERE d.user_id = m.user_id AND d.status = 'verified')
           THEN m.mid
         END,
         public.mid_score(m.user_id), public.mid_tier_title(public.mid_score(m.user_id)),
         m.phone_verified, m.issued_by,
         (SELECT count(*)::int FROM public.conscience_cycles k
          WHERE k.seller_id = m.user_id AND k.outcome IN ('clean', 'flagged'))
  FROM public.mid_identities m
  LEFT JOIN public.profiles p ON p.id = m.user_id
  WHERE m.user_id = _user_id AND public.feature_mode('mid') = 'motorcars'
$$;

-- ---------------------------------------------------------------------------
-- 5. The hourly run, where pg_cron can be used
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  BEGIN
    CREATE EXTENSION IF NOT EXISTS pg_cron;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'pg_cron is unavailable, so Conscience cycles advance when sellers visit or an admin runs them';
  END;
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.schedule('conscience-cycles', '17 * * * *', 'SELECT public.conscience_run()');
  END IF;
END $$;

-- The Motorcars version of Conscience now exists, so admins may switch it on
CREATE OR REPLACE FUNCTION public.motorcars_feature_built(_feature text)
RETURNS boolean
LANGUAGE sql IMMUTABLE
SET search_path TO 'public'
AS $$ SELECT _feature IN ('mid', 'oio', 'wavechat', 'conscience') $$;

COMMIT;

